//! End-to-end C++ OpenEXR parity gate for `exr-core`'s uncompressed scanline
//! read/write path.
//!
//! This integration test proves our reader/writer interoperate with a *real*
//! C++ OpenEXR (the vcpkg `OpenEXR-3_4` library) byte/pixel-exactly, in BOTH
//! directions:
//!
//!   (a) **C++ -> ours (read):** the committed `tests/parity/golden.exr` is a
//!       file written by genuine C++ OpenEXR (regenerated by
//!       `cargo run -p xtask -- parity-exr`).  We read it with our
//!       [`InputFile`] and assert every pixel's exact bits and the header's
//!       required + custom attributes match the KNOWN deterministic image.
//!
//!   (b) **ours -> C++ (write):** we write the SAME known image with our
//!       [`OutputFile`] to a temp file, then invoke the C++ oracle's `read`
//!       mode on it and assert C++ reads back every pixel + header attribute
//!       exactly as the known image.  This direction runs only when the oracle
//!       executable is provided via the `EXR_ORACLE_EXE` env var (set by
//!       xtask); otherwise it is skipped-with-note so `cargo test` works
//!       standalone.
//!
//! The KNOWN image is defined ONCE here and must match `oracle.cpp` exactly:
//!   * 7x5, data/display window [(0,0)..(6,4)], NO_COMPRESSION, INCREASING_Y.
//!   * channels (stored alphabetically): A,B,G,R,Z ; R,G,B = HALF, A,Z = FLOAT.
//!   * pixel pattern, idx = y*WIDTH + x:
//!     `R = half(1.0 + idx*0.5)`, `G = half(100.0 + idx*0.25)`,
//!     `B = half(-50.0 + idx*1.0)`, `A = f32(idx*0.013 + 0.25)`, `Z = f32(idx*100.0)`.
//!   * header: owner(string)="exr-rs", parityTag(int)=31337.
//!
//! # 3.4 vs 3.3.11
//! vcpkg OpenEXR is 3.4; exr-core targets 3.3.11.  The uncompressed-scanline
//! on-disk format is identical across those versions, so any mismatch here is a
//! real interop bug, not a version artifact.

use std::panic::{AssertUnwindSafe, catch_unwind};
use std::path::{Path, PathBuf};
use std::process::Command;

use exr_core::attr::{
    Channel, ChannelList, ChannelListAttribute, Compression, ExrString, LineOrder, Name, PixelType,
};
use exr_core::frame_buffer::{FrameBuffer, Slice};
use exr_core::header::Header;
use exr_core::scanline::{InputFile, OutputFile};
use exr_core::{
    Chromaticities, ChromaticitiesAttribute, IntAttribute, KeyCode, KeyCodeAttribute, MemIStream,
    MemOStream, Rational, RationalAttribute, StdIfStream, StringAttribute,
};

use imath_rs::{Half, V2f};

mod support;

/// The KNOWN scanline image. **Keep in lockstep with `tests/parity/oracle.cpp`**
/// (`WIDTH`/`HEIGHT`/`is_flat`/`*_val` there) — the two definitions are the one
/// contract this whole file rests on and are deliberately textually identical.
///
/// It used to be 7x5. That is a SINGLE chunk for every codec and too
/// small for PIZ / DWAA / DWAB / HTJ2K to shrink, so C++ stored those chunks
/// raw (490 of 490 bytes) and their "byte-identical to C++" goldens proved only
/// the header and the raw-store rule — the codecs themselves had never been
/// compared with C++ at all. 67x43 is multi-chunk
/// for ZIP (16 lines), B44 (4), DWA (32) and PIZ, is not a multiple of
/// 4/8/16/32, and compresses.
const WIDTH: i32 = 67;
const HEIGHT: i32 = 43;

/// Channels in the KNOWN image: A, B, G, R, U, Z.
const NUM_CHANNELS: i32 = 6;

// --- KNOWN deterministic pixel formulas (must equal oracle.cpp) ------------

/// The constant rectangle, aligned to 4 in both axes so it covers WHOLE B44
/// blocks: B44A only emits its 3-byte flat block when all 16 samples of a 4x4
/// block are equal, which no gradient can produce. Without it the B44 and B44A
/// goldens differed by exactly one byte (the compression attribute) and B44A's
/// only distinguishing codepath never ran.
fn is_flat(idx: i32) -> bool {
    let (x, y) = (idx % WIDTH, idx / WIDTH);
    (8..40).contains(&x) && (8..24).contains(&y)
}

fn r_val(idx: i32) -> f32 { if is_flat(idx) { 0.5 } else { 1.0 + idx as f32 * 0.5 } }
fn g_val(idx: i32) -> f32 { if is_flat(idx) { 0.25 } else { 100.0 + idx as f32 * 0.25 } }
fn b_val(idx: i32) -> f32 { if is_flat(idx) { -1.0 } else { -50.0 + idx as f32 * 1.0 } }
fn a_val(idx: i32) -> f32 { if is_flat(idx) { 0.75 } else { (idx % 16) as f32 * 0.013 + 0.25 } }
fn z_val(idx: i32) -> f32 { if is_flat(idx) { 1.0 } else { idx as f32 * 4.0 } }
fn u_val(idx: i32) -> u32 { if is_flat(idx) { 7 } else { idx as u32 * 3 + 11 } }

/// Expected on-disk HALF bits for a channel/pixel (round-to-nearest-even,
/// identical IEEE conversion on both sides).
fn half_bits(v: f32) -> u16 {
    Half::from(v).bits()
}

/// The exact f32 bits a FLOAT channel/pixel carries.
fn float_bits(v: f32) -> u32 {
    v.to_bits()
}

/// The f32 bits a FLOAT channel/pixel carries **after PXR24's lossy 24-bit
/// quantisation** (the deterministic decode result for a PXR24 file).
///
/// PXR24 rounds the significand to 15 bits (`float_to_float24`) and drops the
/// low mantissa byte; the decode reconstructs that low byte as 0, so the
/// decoded float bits are `float_to_float24(v) << 8`.  HALF channels are
/// lossless under PXR24, so only FLOAT uses this.
fn pxr24_float_bits(v: f32) -> u32 {
    exr_core::compressor::pxr24::float_to_float24(v) << 8
}

// ---------------------------------------------------------------------------
// Shared image construction (matches the oracle's known image)
// ---------------------------------------------------------------------------

/// Build the KNOWN header: A,B,G,R,U,Z channels + owner/parityTag attrs.
fn known_header() -> Header {
    let mut h = Header::with_dimensions(
        WIDTH,
        HEIGHT,
        1.0,
        V2f { x: 0.0, y: 0.0 },
        1.0,
        LineOrder::IncreasingY,
        Compression::NoCompression,
    )
    .unwrap();

    let mut cl = ChannelList::new();
    cl.insert("R", Channel::new(PixelType::Half, 1, 1, false)).unwrap();
    cl.insert("G", Channel::new(PixelType::Half, 1, 1, false)).unwrap();
    cl.insert("B", Channel::new(PixelType::Half, 1, 1, false)).unwrap();
    cl.insert("A", Channel::new(PixelType::Float, 1, 1, false)).unwrap();
    cl.insert("Z", Channel::new(PixelType::Float, 1, 1, false)).unwrap();
    cl.insert("U", Channel::new(PixelType::Uint, 1, 1, false)).unwrap();
    h.insert("channels", ChannelListAttribute::new(cl)).unwrap();

    h.insert("owner", StringAttribute::new(ExrString::from("exr-rs"))).unwrap();
    h.insert("parityTag", IntAttribute::new(31337)).unwrap();
    h
}

/// Interleaved per-pixel layout for the writer/reader frame buffer:
/// `[R half][G half][B half][A f32][Z f32][U u32]` = 2+2+2+4+4+4 = 18 bytes,
/// row-major. Shared with the KNOWN **tiled** image below (same channel set).
const PIXEL_BYTES: usize = 2 + 2 + 2 + 4 + 4 + 4;

/// Byte offset (within a pixel) of each channel in the interleaved buffer.
fn chan_offset(name: &str) -> usize {
    match name {
        "R" => 0,
        "G" => 2,
        "B" => 4,
        "A" => 6,
        "Z" => 10,
        "U" => 14,
        _ => unreachable!("unknown channel {name}"),
    }
}

/// Build the interleaved pixel buffer holding the KNOWN image (native bytes,
/// which the writer converts to little-endian XDR on disk).
fn known_pixel_buffer() -> Vec<u8> {
    let row_bytes = PIXEL_BYTES * WIDTH as usize;
    let mut buf = vec![0u8; row_bytes * HEIGHT as usize];
    for y in 0..HEIGHT {
        for x in 0..WIDTH {
            let idx = y * WIDTH + x;
            let p = y as usize * row_bytes + x as usize * PIXEL_BYTES;
            buf[p..p + 2].copy_from_slice(&half_bits(r_val(idx)).to_ne_bytes());
            buf[p + 2..p + 4].copy_from_slice(&half_bits(g_val(idx)).to_ne_bytes());
            buf[p + 4..p + 6].copy_from_slice(&half_bits(b_val(idx)).to_ne_bytes());
            buf[p + 6..p + 10].copy_from_slice(&a_val(idx).to_ne_bytes());
            buf[p + 10..p + 14].copy_from_slice(&z_val(idx).to_ne_bytes());
            buf[p + 14..p + 18].copy_from_slice(&u_val(idx).to_ne_bytes());
        }
    }
    buf
}

/// FrameBuffer describing the interleaved layout above.
fn known_frame_buffer() -> FrameBuffer {
    let row_bytes = PIXEL_BYTES * WIDTH as usize;
    let mut fb = FrameBuffer::new();
    let mk = |ty: PixelType, off: usize| Slice {
        type_: ty,
        base_offset: off as i64,
        x_stride: PIXEL_BYTES,
        y_stride: row_bytes,
        x_sampling: 1,
        y_sampling: 1,
        fill_value: 0.0,
        x_tile_coords: false,
        y_tile_coords: false,
    };
    fb.insert("R", mk(PixelType::Half, chan_offset("R"))).unwrap();
    fb.insert("G", mk(PixelType::Half, chan_offset("G"))).unwrap();
    fb.insert("B", mk(PixelType::Half, chan_offset("B"))).unwrap();
    fb.insert("A", mk(PixelType::Float, chan_offset("A"))).unwrap();
    fb.insert("Z", mk(PixelType::Float, chan_offset("Z"))).unwrap();
    fb.insert("U", mk(PixelType::Uint, chan_offset("U"))).unwrap();
    fb
}

/// Assert that an interleaved readback buffer holds the KNOWN image exactly
/// (bit-for-bit per channel).
fn assert_buffer_is_known(buf: &[u8]) {
    let row_bytes = PIXEL_BYTES * WIDTH as usize;
    for y in 0..HEIGHT {
        for x in 0..WIDTH {
            let idx = y * WIDTH + x;
            let p = y as usize * row_bytes + x as usize * PIXEL_BYTES;
            let r = u16::from_ne_bytes([buf[p], buf[p + 1]]);
            let g = u16::from_ne_bytes([buf[p + 2], buf[p + 3]]);
            let b = u16::from_ne_bytes([buf[p + 4], buf[p + 5]]);
            let a = u32::from_ne_bytes([buf[p + 6], buf[p + 7], buf[p + 8], buf[p + 9]]);
            let z = u32::from_ne_bytes([buf[p + 10], buf[p + 11], buf[p + 12], buf[p + 13]]);
            let u = u32::from_ne_bytes([buf[p + 14], buf[p + 15], buf[p + 16], buf[p + 17]]);
            assert_eq!(r, half_bits(r_val(idx)), "R mismatch at ({x},{y})");
            assert_eq!(g, half_bits(g_val(idx)), "G mismatch at ({x},{y})");
            assert_eq!(b, half_bits(b_val(idx)), "B mismatch at ({x},{y})");
            assert_eq!(a, float_bits(a_val(idx)), "A mismatch at ({x},{y})");
            assert_eq!(z, float_bits(z_val(idx)), "Z mismatch at ({x},{y})");
            assert_eq!(u, u_val(idx), "U mismatch at ({x},{y})");
        }
    }
}

/// Assert the header carries the KNOWN required + custom attributes, expecting
/// the given `compression` (the only header field that differs between the
/// uncompressed and RLE golden files).
fn assert_header_is_known_comp(h: &Header, compression: Compression) {
    let dw = h.data_window().unwrap();
    assert_eq!((dw.min.x, dw.min.y, dw.max.x, dw.max.y), (0, 0, WIDTH - 1, HEIGHT - 1));
    assert_eq!(h.compression().unwrap(), compression);
    assert_eq!(h.line_order().unwrap(), LineOrder::IncreasingY);

    let owner = h
        .typed_attribute::<ExrString>("owner")
        .unwrap()
        .value
        .as_str()
        .unwrap();
    assert_eq!(owner, "exr-rs", "owner attr mismatch");

    let tag = h.typed_attribute::<i32>("parityTag").unwrap().value;
    assert_eq!(tag, 31337, "parityTag attr mismatch");

    // Channels: A,B,G,R,Z in sorted order with the expected types.
    let chans: Vec<(String, PixelType)> = h
        .channels()
        .unwrap()
        .iter()
        .map(|(n, c)| (n.to_string(), c.type_))
        .collect();
    assert_eq!(
        chans,
        vec![
            ("A".to_string(), PixelType::Float),
            ("B".to_string(), PixelType::Half),
            ("G".to_string(), PixelType::Half),
            ("R".to_string(), PixelType::Half),
            ("U".to_string(), PixelType::Uint),
            ("Z".to_string(), PixelType::Float),
        ],
        "channel list mismatch"
    );
}

/// Convenience wrapper: assert the KNOWN header with NO_COMPRESSION.
fn assert_header_is_known(h: &Header) {
    assert_header_is_known_comp(h, Compression::NoCompression);
}

/// Build the KNOWN header but with a specific compression (for the RLE write
/// direction).
fn known_header_comp(compression: Compression) -> Header {
    let mut h = known_header();
    *h.compression_mut().unwrap() = compression;
    h
}

// ---------------------------------------------------------------------------
// Locate the committed golden.exr next to this test source.
// ---------------------------------------------------------------------------

fn golden_path() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("parity")
        .join("golden.exr")
}

/// Locate the committed RLE-compressed golden EXR (same KNOWN image, RLE codec).
fn golden_rle_path() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("parity")
        .join("golden_rle.exr")
}

/// Locate a committed golden EXR by file name (same KNOWN image, given codec).
fn parity_file(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("parity")
        .join(name)
}

// ===========================================================================
// (a) C++ -> ours : read the C++-written golden EXR with our InputFile.
// ===========================================================================

#[test]
fn cpp_golden_read_by_ours_pixel_exact() {
    let Some(golden) = support::fixture_or_skip(
        "cpp_golden_read_by_ours_pixel_exact",
        golden_path(),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };

    let mut is = StdIfStream::open(golden.to_str().unwrap())
        .expect("open golden.exr");
    let mut inf = InputFile::new(&mut is).expect("InputFile::new on golden.exr");

    // Header must match the KNOWN image (required + custom attrs).
    assert_header_is_known(inf.header());

    // Read all 5 scanlines into the interleaved layout and check every pixel.
    let row_bytes = PIXEL_BYTES * WIDTH as usize;
    let mut out = vec![0u8; row_bytes * HEIGHT as usize];
    let fb = known_frame_buffer();
    inf.set_frame_buffer(&fb).expect("set_frame_buffer");
    inf.read_pixels(0, HEIGHT - 1, &mut out).expect("read_pixels");

    assert_buffer_is_known(&out);
    eprintln!("OK (a) C++ golden.exr read by ours: header + every pixel bit-exact.");
}

/// (a-RLE) Read the C++-written RLE golden EXR with our [`InputFile`] and check
/// every pixel + header attr.  This proves our RLE *decompressor* (predict +
/// reorder inverse + RLE decode + raw-store passthrough) reproduces exactly the
/// bytes a genuine C++ OpenEXR RLE writer produced.
#[test]
fn cpp_rle_golden_read_by_ours_pixel_exact() {
    let Some(golden) = support::fixture_or_skip(
        "cpp_rle_golden_read_by_ours_pixel_exact",
        golden_rle_path(),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };

    let mut is = StdIfStream::open(golden.to_str().unwrap())
        .expect("open golden_rle.exr");
    let mut inf = InputFile::new(&mut is).expect("InputFile::new on golden_rle.exr");

    assert_header_is_known_comp(inf.header(), Compression::Rle);

    let row_bytes = PIXEL_BYTES * WIDTH as usize;
    let mut out = vec![0u8; row_bytes * HEIGHT as usize];
    let fb = known_frame_buffer();
    inf.set_frame_buffer(&fb).expect("set_frame_buffer");
    inf.read_pixels(0, HEIGHT - 1, &mut out).expect("read_pixels");

    assert_buffer_is_known(&out);
    eprintln!("OK (a-RLE) C++ golden_rle.exr read by ours: header + every pixel bit-exact.");
}

/// (a-ZIP/ZIPS) Read a C++-written ZIP/ZIPS golden EXR with our [`InputFile`]
/// and check every pixel + header attr.  This proves our ZIP *decompressor*
/// (zlib inflate via deflate-rs + unpredict/reorder + raw-store passthrough)
/// reproduces exactly the bytes a genuine C++ OpenEXR ZIP writer produced.
fn cpp_zip_golden_read_by_ours(file: &str, compression: Compression) {
    let Some(golden) = support::fixture_or_skip(
        &format!("cpp_zip_golden_read_by_ours({file})"),
        parity_file(file),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };

    let mut is = StdIfStream::open(golden.to_str().unwrap()).expect("open golden");
    let mut inf = InputFile::new(&mut is).expect("InputFile::new on golden");
    assert_header_is_known_comp(inf.header(), compression);

    let row_bytes = PIXEL_BYTES * WIDTH as usize;
    let mut out = vec![0u8; row_bytes * HEIGHT as usize];
    let fb = known_frame_buffer();
    inf.set_frame_buffer(&fb).expect("set_frame_buffer");
    inf.read_pixels(0, HEIGHT - 1, &mut out).expect("read_pixels");
    assert_buffer_is_known(&out);
    eprintln!("OK (a-{file}) C++ {file} read by ours: header + every pixel bit-exact.");
}

#[test]
fn cpp_zip_golden_read_by_ours_pixel_exact() {
    cpp_zip_golden_read_by_ours("golden_zip.exr", Compression::Zip);
}

#[test]
fn cpp_zips_golden_read_by_ours_pixel_exact() {
    cpp_zip_golden_read_by_ours("golden_zips.exr", Compression::Zips);
}

/// (byte-exact ZIP) Our ZIP writer must produce a file **byte-identical** to the
/// C++ ZIP golden, because `deflate-rs` matches libdeflate and the predictor +
/// chunk layout are 1:1.  This is the strongest possible parity check: not just
/// pixel-exact but compressed-byte-exact.  (ZIPS is also checked.)
fn ours_zip_bytes_match_cpp_golden(file: &str, compression: Compression) {
    let Some(golden) = support::fixture_or_skip(
        &format!("ours_zip_bytes_match_cpp_golden({file})"),
        parity_file(file),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };
    let cpp_bytes = std::fs::read(&golden).expect("read golden");

    // Write the SAME known image with our writer + the same codec.
    let header = known_header_comp(compression);
    let pixels = known_pixel_buffer();
    let fb = known_frame_buffer();
    let mut mem = MemOStream::new();
    {
        let mut of = OutputFile::new(&mut mem, &header).unwrap();
        of.set_frame_buffer(&fb).unwrap();
        of.write_pixels(&pixels, HEIGHT).unwrap();
    }
    let our_bytes = mem.into_data();

    assert_eq!(
        our_bytes.len(),
        cpp_bytes.len(),
        "{file}: our file length {} != C++ golden length {} (compressed bytes diverge)",
        our_bytes.len(),
        cpp_bytes.len()
    );
    if our_bytes != cpp_bytes {
        // Find first differing byte to aid diagnosis.
        let first = our_bytes
            .iter()
            .zip(cpp_bytes.iter())
            .position(|(a, b)| a != b)
            .unwrap_or(0);
        panic!(
            "{file}: our ZIP file differs from C++ golden at byte {first} \
             (ours={:#04x} cpp={:#04x}); deflate/predictor/chunk mismatch.",
            our_bytes[first], cpp_bytes[first]
        );
    }
    eprintln!("OK (byte-exact {file}) our ZIP writer is byte-identical to C++ golden ({} bytes).", our_bytes.len());
}

#[test]
fn ours_zip_bytes_byte_identical_to_cpp_golden() {
    ours_zip_bytes_match_cpp_golden("golden_zip.exr", Compression::Zip);
}

#[test]
fn ours_zips_bytes_byte_identical_to_cpp_golden() {
    ours_zip_bytes_match_cpp_golden("golden_zips.exr", Compression::Zips);
}

/// Same check as [`ours_zip_bytes_match_cpp_golden`], but with the
/// header's `zip_level` overridden to a NON-default value (the shared default
/// both sides otherwise use is 4). C++'s golden was produced by
/// `oracle write-zip-level <path> <zip|zips> <level>`, which sets
/// `Header::zipCompressionLevel()` before opening the file
/// (`crates/exr-core/tests/parity/oracle.cpp`). Byte-identical output at a
/// level that is NOT the shared default is real evidence the level is
/// actually plumbed from the header into the deflate call, not just that both
/// sides happen to agree on one hardcoded constant.
fn ours_zip_bytes_match_cpp_golden_at_level(file: &str, compression: Compression, level: i32) {
    let Some(golden) = support::fixture_or_skip(
        &format!("ours_zip_bytes_match_cpp_golden_at_level({file}, level={level})"),
        parity_file(file),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };
    let cpp_bytes = std::fs::read(&golden).expect("read golden");

    let mut header = known_header_comp(compression);
    header.set_zip_level(level);
    let pixels = known_pixel_buffer();
    let fb = known_frame_buffer();
    let mut mem = MemOStream::new();
    {
        let mut of = OutputFile::new(&mut mem, &header).unwrap();
        of.set_frame_buffer(&fb).unwrap();
        of.write_pixels(&pixels, HEIGHT).unwrap();
    }
    let our_bytes = mem.into_data();

    assert_eq!(
        our_bytes.len(),
        cpp_bytes.len(),
        "{file} (level {level}): our file length {} != C++ golden length {} \
         (compressed bytes diverge)",
        our_bytes.len(),
        cpp_bytes.len()
    );
    if our_bytes != cpp_bytes {
        let first = our_bytes
            .iter()
            .zip(cpp_bytes.iter())
            .position(|(a, b)| a != b)
            .unwrap_or(0);
        panic!(
            "{file} (level {level}): our ZIP file differs from C++ golden at byte {first} \
             (ours={:#04x} cpp={:#04x}); zip-level plumbing mismatch.",
            our_bytes[first], cpp_bytes[first]
        );
    }
    eprintln!(
        "OK (byte-exact {file}, level {level}) our ZIP writer is byte-identical to C++ golden \
         ({} bytes).",
        our_bytes.len()
    );
}

#[test]
fn ours_zip_level1_bytes_byte_identical_to_cpp_golden() {
    ours_zip_bytes_match_cpp_golden_at_level("golden_zip_level1.exr", Compression::Zip, 1);
}

