// ===========================================================================
// (b) ours -> C++ : write with our OutputFile, read back with the C++ oracle.
// ===========================================================================

/// One parsed `PIX <chan> <x> <y> <hexbits>` record from the oracle's `read`.
struct PixRec {
    chan: String,
    x: i32,
    y: i32,
    bits: u64,
    is_half: bool,
}

/// Parse the oracle's machine-readable `read` output.
fn parse_oracle_read(stdout: &str) -> (Vec<(String, String, String)>, Vec<PixRec>) {
    let mut attrs = Vec::new();
    let mut pix = Vec::new();
    for line in stdout.lines() {
        let mut it = line.split_whitespace();
        match it.next() {
            Some("ATTR") => {
                let name = it.next().unwrap_or("").to_string();
                let ty = it.next().unwrap_or("").to_string();
                let val = it.collect::<Vec<_>>().join(" ");
                attrs.push((name, ty, val));
            }
            Some("PIX") => {
                let chan = it.next().unwrap().to_string();
                let x: i32 = it.next().unwrap().parse().unwrap();
                let y: i32 = it.next().unwrap().parse().unwrap();
                let hex = it.next().unwrap();
                let is_half = hex.len() == 4;
                let bits = u64::from_str_radix(hex, 16).unwrap();
                pix.push(PixRec { chan, x, y, bits, is_half });
            }
            _ => {}
        }
    }
    (attrs, pix)
}

