/// Tiny owning wrapper so the `OutputFile` borrow and the `StdOfStream` value
/// have clear, non-overlapping lifetimes inside the test block.
struct StdOfStreamWrap(exr_core::StdOfStream);
impl StdOfStreamWrap {
    fn create(path: &str) -> Self {
        StdOfStreamWrap(exr_core::StdOfStream::create(path).expect("create out file"))
    }
}

// ===========================================================================
// DWAA / DWAB (lossy DCT; deterministic).  DWA decode parity is the MUST-HAVE:
// our reader must reproduce genuine C++ OpenEXR's decoded (lossy) pixels exactly
// from a C++-written DWAA/DWAB file.  Byte-exact ENCODE is the GOAL and is
// checked separately (and reported honestly) by the bytes-match test below.
// FLOAT channels (A,Z) here are classified Unknown(A is Float->RLE? no: A=Float
// ->RLE) / Unknown(Z) and survive losslessly; R,G,B (HALF) are DCT-coded.
// ===========================================================================

/// (a-DWA) Our reader's decode of the C++ golden must equal the C++ oracle's
/// decode of the same golden, pixel-for-pixel.  Proves our DWA *decompressor*
/// reproduces genuine C++ OpenEXR decode exactly (the MUST-HAVE gate).
fn cpp_dwa_golden_decode_matches_ours(file: &str, compression: Compression) {
    let name = format!("cpp_dwa_golden_decode_matches_ours({file})");
    let Some(golden) = support::fixture_or_skip(
        &name,
        parity_file(file),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };
    let ours = ours_decode_planes(&golden, compression);
    assert_decode_matches_cpp(&name, &golden, &ours);
}

