fn cpp_dwab_golden_decode_matches_ours_pixel_exact() {
    cpp_dwa_golden_decode_matches_ours("golden_dwab.exr", Compression::Dwab);
}

// ===========================================================================
// Subsampled-channel DWA cross-check (these tests are the oracle verification
// of DWA with subsampled channels).  `oracle.cpp`'s
// `write-dwa-sub` / `dump-dwa-sub` modes (additive; do not touch the KNOWN
// 67x43 image) write a 64x64 scanline DWAA/DWAB file with channels A (HALF,
// x2/y1 -> RLE), B/G/R (HALF, unsampled -> the CSC group), BY (HALF, x2/y2 ->
// standalone LOSSY_DCT), Z (FLOAT, x1/y2 -> UNKNOWN/zlib), and dump every
// channel's own reduced-grid pixels, alphabetically, tightly packed
// little-endian.  Both directions mirror the KNOWN-image DWA tests above.
// ===========================================================================

const DWA_SUB_W: i32 = 64;
const DWA_SUB_H: i32 = 64;

/// The `write-dwa-sub` channel set and pixel formulas -- MUST match
/// `oracle.cpp`'s `sr_val`/`sg_val`/`sb_val`/`sby_val`/`sa_val`/`sz_val` and
/// its `header.channels().insert(...)` calls exactly.
fn dwa_sub_channels() -> ChannelList {
    let mut channels = ChannelList::new();
    channels.insert("R", Channel::new(PixelType::Half, 1, 1, false)).unwrap();
    channels.insert("G", Channel::new(PixelType::Half, 1, 1, false)).unwrap();
    channels.insert("B", Channel::new(PixelType::Half, 1, 1, false)).unwrap();
    channels.insert("BY", Channel::new(PixelType::Half, 2, 2, false)).unwrap();
    channels.insert("A", Channel::new(PixelType::Half, 2, 1, false)).unwrap();
    channels.insert("Z", Channel::new(PixelType::Float, 1, 2, false)).unwrap();
    channels
}

fn dwa_sub_header(compression: Compression) -> Header {
    let mut hdr = Header::with_dimensions(
        DWA_SUB_W,
        DWA_SUB_H,
        1.0,
        V2f { x: 0.0, y: 0.0 },
        1.0,
        LineOrder::IncreasingY,
        compression,
    )
    .unwrap();
    hdr.insert("channels", ChannelListAttribute::new(dwa_sub_channels())).unwrap();
    hdr
}

/// A [`FrameBuffer`] whose per-channel `Slice`s address one CONTIGUOUS output
/// buffer laid out exactly like `oracle.cpp`'s `dump-dwa-sub`: channels in
/// alphabetical order (A, B, BY, G, R, Z), each channel's own tightly packed
/// `(w/xSampling) x (h/ySampling)` plane, no interleaving. Reading (or
/// writing) through this frame buffer therefore produces the SAME byte layout
/// as the committed `.dump` file, so the two can be compared directly.
///
/// Returns the frame buffer plus the total buffer size it addresses.
fn dwa_sub_dump_frame_buffer(channels: &ChannelList) -> (FrameBuffer, usize) {
    let mut fb = FrameBuffer::new();
    let mut offset = 0i64;
    for (name, ch) in channels.iter() {
        let cw = (DWA_SUB_W / ch.x_sampling.max(1)) as usize;
        let chh = (DWA_SUB_H / ch.y_sampling.max(1)) as usize;
        let px = exr_core::misc::pixel_type_size(ch.type_).unwrap();
        fb.insert(
            name,
            Slice {
                type_: ch.type_,
                base_offset: offset,
                x_stride: px,
                y_stride: px * cw,
                x_sampling: ch.x_sampling,
                y_sampling: ch.y_sampling,
                fill_value: 0.0,
                x_tile_coords: false,
                y_tile_coords: false,
            },
        )
        .unwrap();
        offset += (px * cw * chh) as i64;
    }
    (fb, offset as usize)
}

/// The known pixel formulas, in the dump's packed planar layout -- mirrors
/// `oracle.cpp`'s `sr_val`/`sg_val`/`sb_val`/`sby_val`/`sa_val`/`sz_val`
/// exactly (`cx`/`cy` are coordinates on the CHANNEL's own reduced grid).
fn dwa_sub_pixel_buffer() -> Vec<u8> {
    let channels = dwa_sub_channels();
    let mut out = Vec::new();
    for (name, ch) in channels.iter() {
        let cw = (DWA_SUB_W / ch.x_sampling.max(1)) as usize;
        let chh = (DWA_SUB_H / ch.y_sampling.max(1)) as usize;
        for cy in 0..chh {
            for cx in 0..cw {
                let (cxf, cyf) = (cx as f32, cy as f32);
                match name.to_str().unwrap_or("") {
                    "R" => out.extend_from_slice(&Half::from_f32(1.0 + (cyf * DWA_SUB_W as f32 + cxf) * 0.05).bits().to_le_bytes()),
                    "G" => out.extend_from_slice(&Half::from_f32(100.0 + (cyf * DWA_SUB_W as f32 + cxf) * 0.03).bits().to_le_bytes()),
                    "B" => out.extend_from_slice(&Half::from_f32(-50.0 + (cyf * DWA_SUB_W as f32 + cxf) * 0.07).bits().to_le_bytes()),
                    "BY" => out.extend_from_slice(&Half::from_f32(10.0 + (cyf * (DWA_SUB_W as f32 / 2.0) + cxf) * 0.3).bits().to_le_bytes()),
                    "A" => out.extend_from_slice(&Half::from_f32(-5.0 + (cyf * (DWA_SUB_W as f32 / 2.0) + cxf) * 0.2).bits().to_le_bytes()),
                    "Z" => out.extend_from_slice(&((cyf * DWA_SUB_W as f32 + cxf) * 4.0).to_le_bytes()),
                    _ => unreachable!("dwa_sub_channels() must match this match arm set"),
                }
                let _ = ch;
            }
        }
    }
    out
}

/// (a-DWA-sub) Our reader's decode of the C++ subsampled-DWA golden must equal
/// the C++ oracle's own decode dump of that golden, byte-for-byte (the
/// dump-layout Slice sampling makes "byte-for-byte" and "pixel-for-pixel"
/// coincide here). The MUST-HAVE gate, same shape as the KNOWN-image DWA test.
fn cpp_dwa_sub_golden_decode_matches_ours(file: &str, compression: Compression) {
    let name = format!("cpp_dwa_sub_golden_decode_matches_ours({file})");
    let Some(golden) = support::fixture_or_skip(
        &name,
        parity_file(file),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };
    let dump_path = PathBuf::from(format!("{}.dump", golden.display()));
    let Some(dump_path) = support::fixture_or_skip(
        &name,
        dump_path,
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ decode dumps.",
    ) else {
        return;
    };
    let cpp_dump = std::fs::read(&dump_path).unwrap_or_else(|e| panic!("read {}: {e}", dump_path.display()));

    let mut is = StdIfStream::open(golden.to_str().unwrap()).expect("open golden");
    let mut inf = InputFile::new(&mut is).expect("InputFile::new on golden");
    assert_eq!(inf.header().compression().unwrap(), compression, "{name}: header compression mismatch");
    let channels = dwa_sub_channels();
    let (fb, total) = dwa_sub_dump_frame_buffer(&channels);
    let mut ours = vec![0u8; total];
    inf.set_frame_buffer(&fb).expect("set_frame_buffer");
    inf.read_pixels(0, DWA_SUB_H - 1, &mut ours).expect("read_pixels");

    assert_eq!(ours.len(), cpp_dump.len(), "{name}: decode length mismatch");
    if ours != cpp_dump {
        let at = ours.iter().zip(&cpp_dump).position(|(a, b)| a != b).unwrap_or(0);
        panic!(
            "{name}: our decode differs from the committed C++ decode at byte {at} \
             (ours={:#04x} cpp={:#04x})",
            ours[at], cpp_dump[at]
        );
    }
    eprintln!("OK {name}: our decode == the committed C++ decode ({} bytes).", cpp_dump.len());
}

