/// (b-DWA-sub) Write the subsampled-channel image with OUR writer, have the
/// C++ oracle decode our file via `dump-dwa-sub`, and compare that against
/// the oracle's decode of ITS OWN golden written from the SAME pixel formulas
/// -- both are C++ decodes, so this proves our WRITER emits a subsampled-DWA
/// stream a genuine C++ OpenEXR reader decodes exactly (not merely that our
/// own reader agrees with our own writer).
fn ours_dwa_sub_written_read_by_cpp_oracle_pixel_exact(golden_file: &str, compression: Compression) {
    let name = format!("ours_dwa_sub_written_read_by_cpp_oracle_pixel_exact({golden_file})");
    let Some(oracle) = support::oracle_or_skip(&name) else {
        return;
    };
    let Some(golden) = support::fixture_or_skip(
        &name,
        parity_file(golden_file),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };
    let golden_dump_path = PathBuf::from(format!("{}.dump", golden.display()));
    let Some(golden_dump_path) = support::fixture_or_skip(
        &name,
        golden_dump_path,
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ decode dumps.",
    ) else {
        return;
    };
    let cpp_golden_dump =
        std::fs::read(&golden_dump_path).unwrap_or_else(|e| panic!("read {}: {e}", golden_dump_path.display()));

    // 1) Write the SAME image with OUR writer.
    let out_path = PathBuf::from(env!("CARGO_TARGET_TMPDIR"))
        .join(format!("parity_exr_ours_{}", golden_file));
    {
        let header = dwa_sub_header(compression);
        let channels = dwa_sub_channels();
        let (fb, _total) = dwa_sub_dump_frame_buffer(&channels);
        let pixels = dwa_sub_pixel_buffer();
        let mut os = StdOfStreamWrap::create(out_path.to_str().unwrap());
        let mut of = OutputFile::new(&mut os.0, &header).unwrap();
        of.set_frame_buffer(&fb).unwrap();
        of.write_pixels(&pixels, DWA_SUB_H).unwrap();
    }

    // 2) Have the C++ oracle decode OUR file via the SAME `dump-dwa-sub` mode
    //    used to produce the committed golden dump.
    let ours_dump_path = PathBuf::from(env!("CARGO_TARGET_TMPDIR"))
        .join(format!("parity_exr_ours_{}.dump", golden_file));
    let output = Command::new(&oracle)
        .arg("dump-dwa-sub")
        .arg(&out_path)
        .arg(&ours_dump_path)
        .output()
        .expect("failed to run oracle dump-dwa-sub");
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(output.status.success(), "oracle dump-dwa-sub failed (status {}):\nstderr:\n{stderr}", output.status);
    let ours_dump =
        std::fs::read(&ours_dump_path).unwrap_or_else(|e| panic!("read {}: {e}", ours_dump_path.display()));

    // 3) Both are C++ decodes of the SAME formulas -> must match exactly.
    assert_eq!(ours_dump.len(), cpp_golden_dump.len(), "{name}: decode length mismatch");
    if ours_dump != cpp_golden_dump {
        let at = ours_dump.iter().zip(&cpp_golden_dump).position(|(a, b)| a != b).unwrap_or(0);
        panic!(
            "{name}: C++ decode of OUR file differs from C++ decode of the golden at byte {at} \
             (ours={:#04x} cpp={:#04x}) -- our writer is not yet byte/pixel-exact for subsampled DWA",
            ours_dump[at], cpp_golden_dump[at]
        );
    }
    eprintln!("OK {name}: C++ decode of our file == C++ decode of the golden ({} bytes).", ours_dump.len());
}

