// ===========================================================================
// HTJ2K256 / HTJ2K32 (OpenEXR 3.4 High-Throughput JPEG 2000; lossy).
//
// HTJ2K decode parity is the MUST-HAVE: our reader must reproduce genuine C++
// OpenEXR 3.4's decoded pixels exactly from a C++-written HTJ2K file (both sides
// decode the identical on-disk codestream).  Byte-exact ENCODE is the GOAL and
// is reported honestly by the bytes-match test — it depends on our `jph-rs`
// (OpenJPH 0.26.3 port) producing the same codestream as the OpenJPH bundled in
// the vcpkg OpenEXR 3.4 build (0.27.0); a minor-version divergence there does
// not affect decode parity.  The (b) direction confirms C++ 3.4 decodes OUR
// HTJ2K file the same way it decodes its own golden.
//
// Reuses the lossy-codec helpers `ours_decode_to_pix`, `oracle_read_pix`, and
// `pix_map` (identical cross-check shape to B44/DWA).
// ===========================================================================

/// (a-HTJ2K) Our reader's decode of the C++ golden must equal the C++ oracle's
/// decode of the same golden, pixel-for-pixel.  Proves our HTJ2K *decompressor*
/// (jph-rs codestream decode + channel-map scatter) reproduces genuine C++
/// OpenEXR 3.4 decode exactly (the MUST-HAVE gate).
fn cpp_htj2k_golden_decode_matches_ours(file: &str, compression: Compression) {
    let name = format!("cpp_htj2k_golden_decode_matches_ours({file})");
    let Some(golden) = support::fixture_or_skip(
        &name,
        parity_file(file),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };

    // HTJ2K is LOSSLESS (`ImfCompression.cpp` registers it with lossy=false and
    // `internal_ht.cpp` calls `cod.set_reversible(true)`), so the strongest
    // available reference is not C++'s decode but the KNOWN image itself: every
    // sample of the C++-written golden must come back bit-identical to the
    // source. The old form tolerated an absolute error of 1.0 and, without the
    // oracle, checked only the pixel COUNT.
    let mut is = StdIfStream::open(golden.to_str().unwrap()).expect("open golden");
    let mut inf = InputFile::new(&mut is).expect("InputFile::new on golden");
    assert_header_is_known_comp(inf.header(), compression);
    let row_bytes = PIXEL_BYTES * WIDTH as usize;
    let mut out = vec![0u8; row_bytes * HEIGHT as usize];
    let fb = known_frame_buffer();
    inf.set_frame_buffer(&fb).expect("set_frame_buffer");
    inf.read_pixels(0, HEIGHT - 1, &mut out).expect("read_pixels");
    assert_buffer_is_known(&out);
    eprintln!("OK (a-{file}) HTJ2K is lossless: the C++ golden decodes to the KNOWN image exactly.");
}

