// ###########################################################################
// TILED parity — TiledOutputFile / TiledInputFile vs the
// real C++ OpenEXR (Imf::TiledOutputFile / Imf::TiledInputFile), BOTH directions,
// ONE_LEVEL + MIPMAP, lossless exact + lossy within-threshold / cross-decode.
//
// The KNOWN tiled image is defined ONCE here and MUST match oracle.cpp exactly:
//   * 20x15, tile 8x8 -> 3x2 tiles at level 0 (partial right + bottom tiles).
//   * channels A,B,G,R,Z (alphabetical); R,G,B = HALF, A,Z = FLOAT.
//   * per-pixel formula keyed on coords RELATIVE to the level data window
//     (px, py) and a per-level bias `lvlbias = lx*7 + ly*13`:
//       tidx = py*levelWidth + px
//       R = half(1.0  + (tidx+lvlbias)*0.5)
//       G = half(100.0 + tidx*0.25 + lvlbias)
//       B = half(-50.0 + tidx*1.0  - lvlbias)
//       A = f32((tidx+lvlbias)*0.013 + 0.25)
//       Z = f32(tidx*100.0 + lvlbias)
//   * header: owner(string)="exr-rs", parityTag(int)=31337, INCREASING_Y,
//     ROUND_DOWN; an off-origin variant uses data window min=(11,7).
// ###########################################################################

use exr_core::attr::{Box2iAttribute, LevelMode, LevelRoundingMode, TileDescription, TileDescriptionAttribute};
use exr_core::header::TILED_IMAGE;
use exr_core::tiled::{TiledInputFile, TiledOutputFile};
use imath_rs::{Box2i, V2i};

/// The KNOWN tiled image. **Keep in lockstep with `tests/parity/oracle.cpp`.**
///
/// It was 20x15 with 8x8 tiles, which is too little data per tile for PIZ or
/// DWAB to shrink one: `golden_tiled_piz_one.exr` was byte-for-byte the size of
/// `golden_tiled_none_one.exr` (4790) because every tile was stored raw, so the
/// tiled PIZ/DWAB "parity" tests never ran the codec. 68x44 with 32x32 tiles
/// keeps the partial right/bottom edge tiles (3 x 2 tiles at level 0) and gives
/// each tile enough data to compress.
const TWIDTH: i32 = 68;
const THEIGHT: i32 = 44;
const TILE_SIZE: u32 = 32;

// --- KNOWN tiled pixel formulas (must equal oracle.cpp, byte-for-byte) ------

fn t_r_val(tidx: i32, lvlbias: i32) -> f32 { 1.0 + (tidx + lvlbias) as f32 * 0.5 }
fn t_g_val(tidx: i32, lvlbias: i32) -> f32 { 100.0 + tidx as f32 * 0.25 + lvlbias as f32 }
fn t_b_val(tidx: i32, lvlbias: i32) -> f32 { -50.0 + tidx as f32 * 1.0 - lvlbias as f32 }
fn t_a_val(tidx: i32, lvlbias: i32) -> f32 { ((tidx + lvlbias) % 16) as f32 * 0.013 + 0.25 }
fn t_z_val(tidx: i32, lvlbias: i32) -> f32 { (tidx + lvlbias) as f32 * 4.0 }
fn t_u_val(tidx: i32, lvlbias: i32) -> u32 { (tidx * 3 + lvlbias + 11) as u32 }

/// Per-level bias (lx == ly == l for ONE_LEVEL/MIPMAP).
fn lvl_bias(lx: i32, ly: i32) -> i32 { lx * 7 + ly * 13 }

/// Build the KNOWN tiled header (data window at `(min_x, min_y)`).
fn known_tiled_header(min_x: i32, min_y: i32, comp: Compression, mode: LevelMode) -> Header {
    let mut h = Header::with_dimensions(
        TWIDTH,
        THEIGHT,
        1.0,
        V2f { x: 0.0, y: 0.0 },
        1.0,
        LineOrder::IncreasingY,
        comp,
    )
    .unwrap();
    // Override data + display window to the requested (possibly off-origin) box.
    let dw = Box2i::from_min_max(
        V2i { x: min_x, y: min_y },
        V2i { x: min_x + TWIDTH - 1, y: min_y + THEIGHT - 1 },
    );
    h.insert("dataWindow", Box2iAttribute::new(dw)).unwrap();
    h.insert("displayWindow", Box2iAttribute::new(dw)).unwrap();
    h.set_type(TILED_IMAGE).unwrap();
    h.insert(
        "tiles",
        TileDescriptionAttribute::new(TileDescription {
            x_size: TILE_SIZE,
            y_size: TILE_SIZE,
            mode,
            rounding_mode: LevelRoundingMode::RoundDown,
        }),
    )
    .unwrap();

    let mut cl = ChannelList::new();
    cl.insert("R", Channel::new(PixelType::Half, 1, 1, false)).unwrap();
    cl.insert("G", Channel::new(PixelType::Half, 1, 1, false)).unwrap();
    cl.insert("B", Channel::new(PixelType::Half, 1, 1, false)).unwrap();
    cl.insert("A", Channel::new(PixelType::Float, 1, 1, false)).unwrap();
    cl.insert("Z", Channel::new(PixelType::Float, 1, 1, false)).unwrap();
    cl.insert("U", Channel::new(PixelType::Uint, 1, 1, false)).unwrap();
    h.insert("channels", ChannelListAttribute::new(cl)).unwrap();

    h.insert("owner", StringAttribute::new(ExrString::from("exr-rs"))).unwrap();
    h.insert("parityTag", IntAttribute::new(31337)).unwrap();
    h
}

/// Build the interleaved KNOWN pixel buffer + a FrameBuffer for ONE level whose
/// data window is `level` (its min addresses the plane origin via base_offset).
/// Returns `(buffer, frame_buffer)`.  Layout matches the scanline interleaved
/// `[R half][G half][B half][A f32][Z f32][U u32]` = 18 bytes/pixel.
fn known_tiled_level(level: Box2i, lvlbias: i32) -> (Vec<u8>, FrameBuffer) {
    let lw = level.max.x - level.min.x + 1;
    let lh = level.max.y - level.min.y + 1;
    let row_bytes = PIXEL_BYTES * lw as usize;
    let mut buf = vec![0u8; row_bytes * lh as usize];
    for py in 0..lh {
        for px in 0..lw {
            let tidx = py * lw + px;
            let p = py as usize * row_bytes + px as usize * PIXEL_BYTES;
            buf[p..p + 2].copy_from_slice(&half_bits(t_r_val(tidx, lvlbias)).to_ne_bytes());
            buf[p + 2..p + 4].copy_from_slice(&half_bits(t_g_val(tidx, lvlbias)).to_ne_bytes());
            buf[p + 4..p + 6].copy_from_slice(&half_bits(t_b_val(tidx, lvlbias)).to_ne_bytes());
            buf[p + 6..p + 10].copy_from_slice(&t_a_val(tidx, lvlbias).to_ne_bytes());
            buf[p + 10..p + 14].copy_from_slice(&t_z_val(tidx, lvlbias).to_ne_bytes());
            buf[p + 14..p + 18].copy_from_slice(&t_u_val(tidx, lvlbias).to_ne_bytes());
        }
    }
    // base_offset addresses (level.min); absolute pixel (x,y) lands at
    // base + (y-min_y)*yStride + (x-min_x)*xStride, so base = -(min*strides).
    let x_stride = PIXEL_BYTES as i64;
    let y_stride = row_bytes as i64;
    let base_offset = -(level.min.y as i64 * y_stride + level.min.x as i64 * x_stride);
    let mk = |ty: PixelType, off: usize| Slice {
        type_: ty,
        base_offset: base_offset + off as i64,
        x_stride: PIXEL_BYTES,
        y_stride: row_bytes,
        x_sampling: 1,
        y_sampling: 1,
        fill_value: 0.0,
        x_tile_coords: false,
        y_tile_coords: false,
    };
    let mut fb = FrameBuffer::new();
    fb.insert("R", mk(PixelType::Half, chan_offset("R"))).unwrap();
    fb.insert("G", mk(PixelType::Half, chan_offset("G"))).unwrap();
    fb.insert("B", mk(PixelType::Half, chan_offset("B"))).unwrap();
    fb.insert("A", mk(PixelType::Float, chan_offset("A"))).unwrap();
    fb.insert("Z", mk(PixelType::Float, chan_offset("Z"))).unwrap();
    fb.insert("U", mk(PixelType::Uint, chan_offset("U"))).unwrap();
    (buf, fb)
}

/// One decoded pixel of a tiled level, keyed by (level, chan, x, y) where x/y
/// are RELATIVE to the level data-window min — same key the oracle emits.
#[derive(Clone)]
struct TPixRec {
    level: i32,
    chan: String,
    x: i32,
    y: i32,
    bits: u64,
    is_half: bool,
}

/// Per-level data window `lx -> (minx, miny, maxx, maxy)` (keeps the decoder's
/// return type simple — avoids a clippy `type_complexity` nag).
type LevelDwMap = std::collections::HashMap<i32, (i32, i32, i32, i32)>;

/// Parsed `read-tiled` oracle output: (tiledesc, levelmode, compression, dw,
/// numlevels, attrs, per-level data windows, pixels).
struct TiledRead {
    tile_x: u32,
    tile_y: u32,
    level_mode: i32,
    compression: i32,
    num_levels: i32,
    attrs: Vec<(String, String, String)>,
    levels: std::collections::HashMap<i32, (i32, i32, i32, i32)>,
    pix: Vec<TPixRec>,
}

fn parse_oracle_read_tiled(stdout: &str) -> TiledRead {
    let mut tr = TiledRead {
        tile_x: 0,
        tile_y: 0,
        level_mode: -1,
        compression: -1,
        num_levels: 0,
        attrs: Vec::new(),
        levels: std::collections::HashMap::new(),
        pix: Vec::new(),
    };
    for line in stdout.lines() {
        let mut it = line.split_whitespace();
        match it.next() {
            Some("TILEDESC") => {
                tr.tile_x = it.next().unwrap().parse().unwrap();
                tr.tile_y = it.next().unwrap().parse().unwrap();
                // mode + rounding follow but we read mode via LEVELMODE.
            }
            Some("LEVELMODE") => tr.level_mode = it.next().unwrap().parse().unwrap(),
            Some("COMPRESSION") => tr.compression = it.next().unwrap().parse().unwrap(),
            Some("NUMLEVELS") => tr.num_levels = it.next().unwrap().parse().unwrap(),
            Some("ATTR") => {
                let name = it.next().unwrap_or("").to_string();
                let ty = it.next().unwrap_or("").to_string();
                let val = it.collect::<Vec<_>>().join(" ");
                tr.attrs.push((name, ty, val));
            }
            Some("LEVEL") => {
                let l: i32 = it.next().unwrap().parse().unwrap();
                let minx: i32 = it.next().unwrap().parse().unwrap();
                let miny: i32 = it.next().unwrap().parse().unwrap();
                let maxx: i32 = it.next().unwrap().parse().unwrap();
                let maxy: i32 = it.next().unwrap().parse().unwrap();
                tr.levels.insert(l, (minx, miny, maxx, maxy));
            }
            Some("TPIX") => {
                let level: i32 = it.next().unwrap().parse().unwrap();
                let chan = it.next().unwrap().to_string();
                let x: i32 = it.next().unwrap().parse().unwrap();
                let y: i32 = it.next().unwrap().parse().unwrap();
                let hex = it.next().unwrap();
                let is_half = hex.len() == 4;
                let bits = u64::from_str_radix(hex, 16).unwrap();
                tr.pix.push(TPixRec { level, chan, x, y, bits, is_half });
            }
            _ => {}
        }
    }
    tr
}

/// Locate the committed tiled golden by suffix (codec_levelmode[_offset]).
fn tiled_golden(suffix: &str) -> PathBuf {
    parity_file(&format!("golden_tiled_{suffix}.exr"))
}

/// The levels (lx, ly) of a tiled image given its mode (lx == ly here).
fn tiled_levels(mode: LevelMode, num_levels: i32) -> Vec<(i32, i32)> {
    match mode {
        LevelMode::OneLevel => vec![(0, 0)],
        LevelMode::MipmapLevels => (0..num_levels).map(|l| (l, l)).collect(),
        LevelMode::RipmapLevels | LevelMode::Invalid => unreachable!("not used in this gate"),
    }
}

/// Read EVERY pixel of EVERY level of a tiled golden with OUR [`TiledInputFile`]
/// into the per-level decoded records (keyed level/chan/x/y relative to level
/// min).  Also returns the per-level data windows our reader reports.
fn ours_decode_tiled(golden: &Path, mode: LevelMode) -> (Vec<TPixRec>, LevelDwMap) {
    let mut is = StdIfStream::open(golden.to_str().unwrap()).expect("open tiled golden");
    let mut tif = TiledInputFile::new(&mut is).expect("TiledInputFile::new on golden");
    assert!(tif.is_complete(), "offset table must be complete");

    let num_levels = tif.num_levels().unwrap();
    let levels = tiled_levels(mode, num_levels);

    let mut out_pix = Vec::new();
    let mut level_dw = std::collections::HashMap::new();
    for &(lx, ly) in &levels {
        let lvl = tif.data_window_for_level(lx, ly).unwrap();
        let lw = lvl.max.x - lvl.min.x + 1;
        let lh = lvl.max.y - lvl.min.y + 1;
        level_dw.insert(lx, (lvl.min.x, lvl.min.y, lvl.max.x, lvl.max.y));

        let row_bytes = PIXEL_BYTES * lw as usize;
        let mut buf = vec![0u8; row_bytes * lh as usize];
        let (_, fb) = known_tiled_level(lvl, lvl_bias(lx, ly)); // reuse the slice layout
        // Replace base so it addresses THIS local buffer (same math as builder).
        tif.set_frame_buffer(&fb).unwrap();
        let nx = tif.num_x_tiles(lx).unwrap();
        let ny = tif.num_y_tiles(ly).unwrap();
        tif.read_tiles(0, nx - 1, 0, ny - 1, lx, ly, &mut buf).unwrap();

        for y in 0..lh {
            for x in 0..lw {
                let p = y as usize * row_bytes + x as usize * PIXEL_BYTES;
                let r = u16::from_ne_bytes([buf[p], buf[p + 1]]) as u64;
                let g = u16::from_ne_bytes([buf[p + 2], buf[p + 3]]) as u64;
                let b = u16::from_ne_bytes([buf[p + 4], buf[p + 5]]) as u64;
                let a = u32::from_ne_bytes([buf[p + 6], buf[p + 7], buf[p + 8], buf[p + 9]]) as u64;
                let z = u32::from_ne_bytes([buf[p + 10], buf[p + 11], buf[p + 12], buf[p + 13]]) as u64;
                let u = u32::from_ne_bytes([buf[p + 14], buf[p + 15], buf[p + 16], buf[p + 17]]) as u64;
                out_pix.push(TPixRec { level: lx, chan: "R".into(), x, y, bits: r, is_half: true });
                out_pix.push(TPixRec { level: lx, chan: "G".into(), x, y, bits: g, is_half: true });
                out_pix.push(TPixRec { level: lx, chan: "B".into(), x, y, bits: b, is_half: true });
                out_pix.push(TPixRec { level: lx, chan: "A".into(), x, y, bits: a, is_half: false });
                out_pix.push(TPixRec { level: lx, chan: "Z".into(), x, y, bits: z, is_half: false });
                out_pix.push(TPixRec { level: lx, chan: "U".into(), x, y, bits: u, is_half: false });
            }
        }
    }
    (out_pix, level_dw)
}

/// Run the oracle `read-tiled` on a path and parse it.
fn oracle_read_tiled(oracle: &Path, path: &Path) -> TiledRead {
    let output = Command::new(oracle)
        .arg("read-tiled")
        .arg(path)
        .output()
        .expect("failed to run oracle read-tiled");
    let stdout = String::from_utf8_lossy(&output.stdout);
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(
        output.status.success(),
        "oracle read-tiled failed (status {}):\nstderr:\n{stderr}",
        output.status
    );
    parse_oracle_read_tiled(&stdout)
}

/// Index TPixRec by (level, chan, x, y) -> (bits, is_half).
fn tpix_map(pix: &[TPixRec]) -> std::collections::HashMap<(i32, String, i32, i32), (u64, bool)> {
    pix.iter()
        .map(|r| ((r.level, r.chan.clone(), r.x, r.y), (r.bits, r.is_half)))
        .collect()
}

/// Expected exact bits of (chan, tidx, lvlbias) for a LOSSLESS codec.
fn t_expected_bits(chan: &str, tidx: i32, lvlbias: i32) -> (u64, bool) {
    match chan {
        "R" => (half_bits(t_r_val(tidx, lvlbias)) as u64, true),
        "G" => (half_bits(t_g_val(tidx, lvlbias)) as u64, true),
        "B" => (half_bits(t_b_val(tidx, lvlbias)) as u64, true),
        "A" => (t_a_val(tidx, lvlbias).to_bits() as u64, false),
        "Z" => (t_z_val(tidx, lvlbias).to_bits() as u64, false),
        "U" => (t_u_val(tidx, lvlbias) as u64, false),
        other => panic!("unknown channel {other}"),
    }
}

// ---------------------------------------------------------------------------
// (a) C++ -> ours (LOSSLESS): our TiledInputFile reads each committed golden,
//     every level's every pixel bit-exact vs the KNOWN formula.
// ---------------------------------------------------------------------------
fn cpp_tiled_lossless_read_by_ours(suffix: &str, comp: Compression, mode: LevelMode) {
    let Some(golden) = support::fixture_or_skip(
        &format!("cpp_tiled_lossless_read_by_ours({suffix})"),
        tiled_golden(suffix),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };

    // Sanity: header compression matches via a fresh open.
    {
        let mut is = StdIfStream::open(golden.to_str().unwrap()).expect("open golden");
        let tif = TiledInputFile::new(&mut is).expect("TiledInputFile::new");
        assert_eq!(tif.compression().unwrap(), comp, "{suffix}: compression mismatch");
        assert_eq!(tif.tile_x_size(), TILE_SIZE, "{suffix}: tileX mismatch");
        assert_eq!(tif.tile_y_size(), TILE_SIZE, "{suffix}: tileY mismatch");
        assert_eq!(tif.level_mode(), mode, "{suffix}: level mode mismatch");
    }

    let (ours, level_dw) = ours_decode_tiled(&golden, mode);
    for rec in &ours {
        let (minx, miny, _, _) = level_dw[&rec.level];
        let lw = level_dw[&rec.level].2 - minx + 1;
        let _ = miny;
        let tidx = rec.y * lw + rec.x;
        let (expected, half) = t_expected_bits(&rec.chan, tidx, lvl_bias(rec.level, rec.level));
        assert_eq!(rec.is_half, half, "{suffix}: chan {} bit-width mismatch", rec.chan);
        assert_eq!(
            rec.bits, expected,
            "{suffix}: level {} chan {} at ({},{}) bits mismatch (lossless not bit-exact vs C++!)",
            rec.level, rec.chan, rec.x, rec.y
        );
    }
    eprintln!(
        "OK (a-tiled {suffix}) ours read all {} pixels of {} level(s) bit-exact vs KNOWN.",
        ours.len(),
        level_dw.len()
    );
}

