/// The header-variant tiled goldens: ROUND_UP level rounding, and RANDOM_Y /
/// DECREASING_Y tile order.
///
/// Each was previously covered only by an attribute-byte unit test, so nothing
/// proved our reader derives the right level sizes under ROUND_UP or reads a
/// file whose tiles are NOT stored in increasing-Y order. Every level's every
/// pixel is still checked against the KNOWN formula, which is position-keyed
/// and therefore order-independent by construction — exactly what makes it a
/// valid oracle for a RANDOM_Y file.
fn cpp_tiled_variant_read_by_ours(
    suffix: &str,
    comp: Compression,
    mode: LevelMode,
    rounding: LevelRoundingMode,
    order: LineOrder,
) {
    let Some(golden) = support::fixture_or_skip(
        &format!("cpp_tiled_variant_read_by_ours({suffix})"),
        tiled_golden(suffix),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };
    {
        let mut is = StdIfStream::open(golden.to_str().unwrap()).expect("open golden");
        let tif = TiledInputFile::new(&mut is).expect("TiledInputFile::new");
        assert_eq!(tif.level_rounding_mode(), rounding, "{suffix}: rounding mode");
        assert_eq!(
            tif.header().line_order().unwrap(),
            order,
            "{suffix}: line order"
        );
    }
    cpp_tiled_lossless_read_by_ours(suffix, comp, mode);
}

