/// `TiledInputFile::raw_tile_data` (C++ `rawTileData`'s in/out coordinate
/// contract) must be an exact
/// `(dx,dy,lx,ly) -> chunk` table lookup, addressed strictly by the
/// coordinates the caller passes -- NOT a physical read cursor that returns
/// "whatever chunk comes next" regardless of the requested coordinate
/// (`OpenEXRCore/chunk.c::validate_and_compute_tile_chunk_off` computes the
/// chunk-table slot purely from the exact input coordinates; there is no
/// cursor branch, confirmed by reading the source).
///
/// Uses a REAL C++-written RANDOM_Y golden (`golden_tiled_zip_one_randomy.exr`)
/// specifically because RANDOM_Y is the line order where "on-disk order"
/// and "canonical (level,y,x) coordinate order" are least likely to
/// coincide. Reads every tile's raw bytes via `raw_tile_data` in ascending
/// coordinate order, then re-opens the SAME file fresh and reads every tile
/// again in DESCENDING coordinate order, and asserts both passes return
/// byte-identical raw data AND the same coordinate echo for every `(dx,
/// dy)`. If `raw_tile_data` were a physical cursor instead of a table
/// lookup, reversing the CALL order would make each call return a
/// DIFFERENT physical chunk than the matching forward-order call for the
/// same logical tile index, so the two passes' results would diverge for at
/// least one tile (any file with more than one tile whose call order isn't
/// a palindrome) -- this is a structural property of the two candidate
/// implementations, not something that needs a synthetic bug injected to
/// verify it would be caught.
#[test]
fn cpp_tiled_zip_one_randomy_raw_tile_data_is_addressed_by_coordinate() {
    let Some(golden) = support::fixture_or_skip(
        "cpp_tiled_zip_one_randomy_raw_tile_data_is_addressed_by_coordinate",
        tiled_golden("zip_one_randomy"),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };

    let (nx, ny) = {
        let mut is = StdIfStream::open(golden.to_str().unwrap()).expect("open golden");
        let tif = TiledInputFile::new(&mut is).expect("TiledInputFile::new");
        assert_eq!(
            tif.header().line_order().unwrap(),
            LineOrder::RandomY,
            "golden must actually be RANDOM_Y for this test to mean anything"
        );
        (tif.num_x_tiles(0).unwrap(), tif.num_y_tiles(0).unwrap())
    };
    assert!(nx > 1 && ny > 1, "need a real multi-tile grid to exercise call-order independence");

    // Forward pass: (dy, dx) ascending.
    let mut forward = std::collections::HashMap::new();
    {
        let mut is = StdIfStream::open(golden.to_str().unwrap()).expect("open golden");
        let mut tif = TiledInputFile::new(&mut is).expect("TiledInputFile::new");
        for dy in 0..ny {
            for dx in 0..nx {
                let (r_dx, r_dy, r_lx, r_ly, data) =
                    tif.raw_tile_data(dx, dy, 0, 0).expect("raw_tile_data (forward)");
                assert_eq!(
                    (r_dx, r_dy, r_lx, r_ly),
                    (dx, dy, 0, 0),
                    "raw_tile_data must echo the exact requested coordinates back, \
                     not some other tile's (forward pass, ({dx},{dy}))"
                );
                forward.insert((dx, dy), data);
            }
        }
    }

    // Reverse pass: a FRESH open, (dy, dx) descending -- the opposite call order.
    let mut reverse = std::collections::HashMap::new();
    {
        let mut is = StdIfStream::open(golden.to_str().unwrap()).expect("open golden");
        let mut tif = TiledInputFile::new(&mut is).expect("TiledInputFile::new");
        for dy in (0..ny).rev() {
            for dx in (0..nx).rev() {
                let (r_dx, r_dy, r_lx, r_ly, data) =
                    tif.raw_tile_data(dx, dy, 0, 0).expect("raw_tile_data (reverse)");
                assert_eq!(
                    (r_dx, r_dy, r_lx, r_ly),
                    (dx, dy, 0, 0),
                    "raw_tile_data must echo the exact requested coordinates back, \
                     not some other tile's (reverse pass, ({dx},{dy}))"
                );
                reverse.insert((dx, dy), data);
            }
        }
    }

    assert_eq!(forward.len(), (nx * ny) as usize);
    assert_eq!(
        forward, reverse,
        "raw_tile_data must return the SAME bytes for the SAME coordinate \
         regardless of the order tiles are requested in -- a table lookup is \
         call-order-independent, a physical read cursor would not be"
    );
}

