/// ROUND_UP must actually change the level count relative to ROUND_DOWN, or the
/// two goldens would be testing the same thing.
#[test]
fn roundup_and_rounddown_mipmaps_differ() {
    let name = "roundup_and_rounddown_mipmaps_differ";
    let Some(up) = support::fixture_or_skip(
        name,
        tiled_golden("zip_mipmap_roundup"),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };
    let Some(down) = support::fixture_or_skip(
        name,
        tiled_golden("zip_mipmap"),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };
    let levels = |path: &Path| -> i32 {
        let mut is = StdIfStream::open(path.to_str().unwrap()).expect("open golden");
        let tif = TiledInputFile::new(&mut is).expect("TiledInputFile::new");
        tif.num_levels().unwrap()
    };
    let (nu, nd) = (levels(&up), levels(&down));
    assert!(
        nu > nd,
        "ROUND_UP must produce MORE mip levels than ROUND_DOWN for {TWIDTH}x{THEIGHT} \
         (got {nu} vs {nd}) -- otherwise the two goldens test the same path"
    );
}

/// "Header wire bytes": the base attribute set (owner/parityTag/
/// channels/compression/dataWindow/displayWindow/lineOrder/
/// pixelAspectRatio/screenWindowCenter/screenWindowWidth) is already proven
/// byte-exact as a side effect of every `*_bytes_byte_identical_to_cpp_golden`
/// test (they compare the WHOLE file, header included). This test adds
/// three structured, multi-field attribute types not otherwise exercised:
/// chromaticities (4 packed `V2f`), a `rational` (`i32` + `u32`), and a
/// `keyCode` (7 packed `i32`) -- exactly the shapes where a field-order bug
/// is plausible and a plain round-trip (write-then-read-with-ourselves)
/// could not catch it (a swapped pair of fields round-trips through our own
/// reader/writer just fine; only a REAL C++ file exposes the mismatch).
#[test]
fn ours_header_attrs_bytes_byte_identical_to_cpp_golden() {
    let Some(golden) = support::fixture_or_skip(
        "ours_header_attrs_bytes_byte_identical_to_cpp_golden",
        parity_file("golden_header_attrs.exr"),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };
    let cpp_bytes = std::fs::read(&golden).expect("read golden");

    let mut header = known_header_comp(Compression::NoCompression);
    header
        .insert(
            "chromaticities",
            ChromaticitiesAttribute::new(Chromaticities {
                red: [0.640, 0.330],
                green: [0.300, 0.600],
                blue: [0.150, 0.060],
                white: [0.3127, 0.3290],
            }),
        )
        .unwrap();
    header
        .insert("myRational", RationalAttribute::new(Rational { n: 7, d: 3 }))
        .unwrap();
    header
        .insert(
            "myKeyCode",
            KeyCodeAttribute::new(KeyCode::new(12, 3, 456789, 42, 7, 4, 64).unwrap()),
        )
        .unwrap();

    let pixels = known_pixel_buffer();
    let fb = known_frame_buffer();
    let mut mem = MemOStream::new();
    {
        let mut of = OutputFile::new(&mut mem, &header).unwrap();
        of.set_frame_buffer(&fb).unwrap();
        of.write_pixels(&pixels, HEIGHT).unwrap();
    }
    let our_bytes = mem.into_data();

    assert_eq!(
        our_bytes.len(),
        cpp_bytes.len(),
        "our file length {} != C++ golden length {} -- one side's header attrs \
         serialize to a different byte count",
        our_bytes.len(),
        cpp_bytes.len()
    );
    if our_bytes != cpp_bytes {
        let first = our_bytes
            .iter()
            .zip(cpp_bytes.iter())
            .position(|(a, b)| a != b)
            .unwrap_or(0);
        panic!(
            "header wire bytes differ at byte {first} (ours={:#04x} cpp={:#04x}); \
             chromaticities/rational/keyCode field order or size mismatch",
            our_bytes[first], cpp_bytes[first]
        );
    }
}

