// ---------------------------------------------------------------------------
// (a-ripmap) RIPMAP -- independent (lx, ly) level grid. Self-contained:
// unlike `ours_decode_tiled`/`tiled_levels`, which key everything by a single
// `i32` level (fine for ONE_LEVEL/MIPMAP where lx == ly, but RIPMAP has MANY
// levels sharing the same lx, e.g. (0,1) and (0,2)), this walks the real 2D
// `(lx, ly)` grid directly against the KNOWN formula -- the same independent
// oracle `cpp_tiled_lossless_read_by_ours` uses, just not funneled through its
// lx-keyed `HashMap`.
// ---------------------------------------------------------------------------
#[test]
fn cpp_tiled_zip_ripmap_read_by_ours() {
    let Some(golden) = support::fixture_or_skip(
        "cpp_tiled_zip_ripmap_read_by_ours",
        tiled_golden("zip_ripmap"),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };

    let mut is = StdIfStream::open(golden.to_str().unwrap()).expect("open golden");
    let mut tif = TiledInputFile::new(&mut is).expect("TiledInputFile::new");
    assert!(tif.is_complete(), "offset table must be complete");
    assert_eq!(tif.compression().unwrap(), Compression::Zip, "compression mismatch");
    assert_eq!(tif.level_mode(), LevelMode::RipmapLevels, "level mode mismatch");

    let nx = tif.num_x_levels();
    let ny = tif.num_y_levels();
    // The 68x44 KNOWN image is non-square, so a genuine 2D ripmap grid must
    // have independent x/y level counts -- if nx == ny here the writer fell
    // back to a diagonal (mipmap-shaped) grid and this test would silently
    // stop proving anything.
    assert_ne!(
        nx, ny,
        "RIPMAP levels for a {TWIDTH}x{THEIGHT} image must have numXLevels != \
         numYLevels, or this golden isn't exercising a real 2D grid"
    );
    assert!(nx > 1 && ny > 1, "expected multiple levels in both axes");

    let mut checked = 0usize;
    for ly in 0..ny {
        for lx in 0..nx {
            assert!(tif.is_valid_level(lx, ly), "({lx},{ly}) must be a valid RIPMAP level");
            let lvl = tif.data_window_for_level(lx, ly).unwrap();
            let lw = lvl.max.x - lvl.min.x + 1;
            let lh = lvl.max.y - lvl.min.y + 1;
            let lvlbias = lvl_bias(lx, ly);

            let row_bytes = PIXEL_BYTES * lw as usize;
            let mut buf = vec![0u8; row_bytes * lh as usize];
            let (_, fb) = known_tiled_level(lvl, lvlbias);
            tif.set_frame_buffer(&fb).unwrap();
            let ntx = tif.num_x_tiles(lx).unwrap();
            let nty = tif.num_y_tiles(ly).unwrap();
            tif.read_tiles(0, ntx - 1, 0, nty - 1, lx, ly, &mut buf).unwrap();

            for y in 0..lh {
                for x in 0..lw {
                    let tidx = y * lw + x;
                    let p = y as usize * row_bytes + x as usize * PIXEL_BYTES;
                    let r = u16::from_ne_bytes([buf[p], buf[p + 1]]) as u64;
                    let g = u16::from_ne_bytes([buf[p + 2], buf[p + 3]]) as u64;
                    let b = u16::from_ne_bytes([buf[p + 4], buf[p + 5]]) as u64;
                    let a = u32::from_ne_bytes([buf[p + 6], buf[p + 7], buf[p + 8], buf[p + 9]]) as u64;
                    let z = u32::from_ne_bytes([buf[p + 10], buf[p + 11], buf[p + 12], buf[p + 13]]) as u64;
                    let u = u32::from_ne_bytes([buf[p + 14], buf[p + 15], buf[p + 16], buf[p + 17]]) as u64;
                    for (chan, bits, is_half) in [
                        ("R", r, true), ("G", g, true), ("B", b, true),
                        ("A", a, false), ("Z", z, false), ("U", u, false),
                    ] {
                        let (expected, half) = t_expected_bits(chan, tidx, lvlbias);
                        assert_eq!(half, is_half, "chan {chan} bit-width mismatch");
                        assert_eq!(
                            bits, expected,
                            "level ({lx},{ly}) chan {chan} at ({x},{y}) bits mismatch vs KNOWN formula"
                        );
                        checked += 1;
                    }
                }
            }
        }
    }
    assert!(
        checked > 0,
        "the RIPMAP level grid must not be empty -- 0 pixels checked means the loop never ran"
    );
}

// ---------------------------------------------------------------------------
// (a-lossy) C++ -> ours (B44/B44A/PXR24/DWAA/DWAB): our reader's decode of the
//     golden == the C++ decode COMMITTED next to it (`<golden>.dump`), byte
//     for byte. The dump is produced by the same oracle that wrote the golden,
//     so this needs no oracle binary at run time -- which is the point: the
//     comparison used to vanish into a pixel COUNT whenever the oracle was
//     absent, i.e. in every plain `cargo test`.
// ---------------------------------------------------------------------------

fn cpp_tiled_lossy_read_by_ours(suffix: &str, _comp: Compression, mode: LevelMode) {
    let name = format!("cpp_tiled_lossy_read_by_ours({suffix})");
    let Some(golden) = support::fixture_or_skip(
        &name,
        tiled_golden(suffix),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };
    let ours = ours_decode_tiled_planes(&golden, mode);
    assert_decode_matches_cpp(&name, &golden, &ours);
}

