// ---------------------------------------------------------------------------
// (b) ours -> C++: our TiledOutputFile writes the KNOWN image; the C++ oracle
//     `read-tiled` reads it back; assert metadata + every pixel.  Lossless:
//     exact vs formula.  Lossy: C++ decode of OUR file == C++ decode of golden.
// ---------------------------------------------------------------------------

/// Write the KNOWN tiled image (all levels, canonical order) with OUR writer to
/// `out_path`.  `min_x/min_y` set the (possibly off-origin) data window.
fn ours_write_tiled(out_path: &Path, comp: Compression, mode: LevelMode, min_x: i32, min_y: i32) {
    let header = known_tiled_header(min_x, min_y, comp, mode);
    let mut os = StdOfStreamWrap::create(out_path.to_str().unwrap());
    let mut tof = TiledOutputFile::new(&mut os.0, &header).unwrap();
    let num_levels = tof.num_levels().unwrap();
    let levels = tiled_levels(mode, num_levels);
    // `set_frame_buffer` installs only the LAYOUT;
    // pixel bytes are passed to `write_tiles` per call, so a fresh
    // per-level buffer is simply a local per iteration — no cross-iteration
    // binding needed.
    for &(lx, ly) in &levels {
        let lvl = tof.data_window_for_tile(0, 0, lx, ly).unwrap(); // any tile gives level min
        // Reconstruct the level data window from the writer accessors.
        let lw = tof.level_width(lx).unwrap();
        let lh = tof.level_height(ly).unwrap();
        let level = Box2i::from_min_max(
            V2i { x: lvl.min.x, y: lvl.min.y },
            V2i { x: lvl.min.x + lw - 1, y: lvl.min.y + lh - 1 },
        );
        let (pixels, fb) = known_tiled_level(level, lvl_bias(lx, ly));
        tof.set_frame_buffer(&fb).unwrap();
        let nx = tof.num_x_tiles(lx).unwrap();
        let ny = tof.num_y_tiles(ly).unwrap();
        tof.write_tiles(&pixels, 0, nx - 1, 0, ny - 1, lx, ly).unwrap();
    }
}


/// Assert the oracle's read-tiled metadata matches the KNOWN image.
fn assert_tiled_meta(tr: &TiledRead, comp: Compression, mode: LevelMode) {
    assert_eq!(tr.tile_x, TILE_SIZE, "tileX mismatch");
    assert_eq!(tr.tile_y, TILE_SIZE, "tileY mismatch");
    assert_eq!(tr.level_mode, mode as i32, "level mode mismatch");
    assert_eq!(tr.compression, comp as i32, "compression mismatch");
    let owner = tr.attrs.iter().find(|(n, ..)| n == "owner");
    assert_eq!(
        owner.map(|(_, t, v)| (t.as_str(), v.as_str())),
        Some(("string", "exr-rs")),
        "owner attr mismatch: {:?}",
        tr.attrs
    );
    let tag = tr.attrs.iter().find(|(n, ..)| n == "parityTag");
    assert_eq!(
        tag.map(|(_, t, v)| (t.as_str(), v.as_str())),
        Some(("int", "31337")),
        "parityTag attr mismatch: {:?}",
        tr.attrs
    );
}

fn ours_write_tiled_lossless_read_by_cpp(
    tmp_name: &str,
    comp: Compression,
    mode: LevelMode,
    min_x: i32,
    min_y: i32,
) {
    let Some(oracle) = support::oracle_or_skip(tmp_name) else { return };

    let out_path = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(tmp_name);
    ours_write_tiled(&out_path, comp, mode, min_x, min_y);

    let tr = oracle_read_tiled(&oracle, &out_path);
    assert_tiled_meta(&tr, comp, mode);
    assert!(!tr.pix.is_empty(), "{tmp_name}: oracle read no pixels");

    for rec in &tr.pix {
        let (minx, _, maxx, _) = tr.levels[&rec.level];
        let lw = maxx - minx + 1;
        let tidx = rec.y * lw + rec.x;
        let (expected, half) = t_expected_bits(&rec.chan, tidx, lvl_bias(rec.level, rec.level));
        assert_eq!(rec.is_half, half, "{tmp_name}: chan {} bit-width", rec.chan);
        assert_eq!(
            rec.bits, expected,
            "{tmp_name}: C++ read divergent bits for level {} chan {} at ({},{})",
            rec.level, rec.chan, rec.x, rec.y
        );
    }
    eprintln!(
        "OK (b-tiled {tmp_name}) ours -> C++ oracle: meta + all {} pixels read back bit-exact.",
        tr.pix.len()
    );
}

