/// (b-lossy) Write the KNOWN image with OUR writer using a lossy codec; the C++
/// oracle's decode of OUR file must equal its decode of the C++ golden
/// (round-trip interop, independent of byte-exact encode).
fn ours_write_tiled_lossy_read_by_cpp(
    tmp_name: &str,
    golden_suffix: &str,
    comp: Compression,
    mode: LevelMode,
) {
    let Some(oracle) = support::oracle_or_skip(tmp_name) else { return };
    let Some(golden) = support::fixture_or_skip(
        tmp_name,
        tiled_golden(golden_suffix),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };

    let out_path = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(tmp_name);
    ours_write_tiled(&out_path, comp, mode, 0, 0);

    let ours = tpix_map(&oracle_read_tiled(&oracle, &out_path).pix);
    let golden_tr = oracle_read_tiled(&oracle, &golden);
    assert!(!golden_tr.pix.is_empty());
    for rec in &golden_tr.pix {
        let key = (rec.level, rec.chan.clone(), rec.x, rec.y);
        let (our_bits, our_half) = ours
            .get(&key)
            .copied()
            .unwrap_or_else(|| panic!("oracle missing tiled pixel {key:?} in our file"));
        assert_eq!(our_half, rec.is_half, "{tmp_name}: chan {} bit-width", rec.chan);
        assert_eq!(
            our_bits, rec.bits,
            "{tmp_name}: C++ decode of OUR file != C++ decode of golden for level {} chan {} at ({},{})",
            rec.level, rec.chan, rec.x, rec.y
        );
    }
    eprintln!(
        "OK (b-tiled {tmp_name}) ours(lossy) -> C++ oracle decode == golden decode for all {} pixels.",
        golden_tr.pix.len()
    );
}

