// ###########################################################################
// DEEP parity gate
// ###########################################################################
//
// The authoritative deep verification: proves our DeepScanLine + DeepTiled
// read/write interoperate with a real C++ OpenEXR (vcpkg OpenEXR-3_4) in BOTH
// directions, pixel(sample)-exact AND count-exact.  Deep is all-lossless
// (NONE/RLE/ZIPS), so every count and every sample bit must match exactly.
//
// The KNOWN deep image (defined identically here and in oracle.cpp):
//   * 8x6 (deep tile 4x4 -> 2x2 tiles); channels (alphabetical) B,G,R=HALF, Z=FLOAT.
//   * VARIABLE per-pixel sample counts N(x,y) = (lx + ly) % 4 with lx/ly the
//     LEVEL-relative coords (gives 0,1,2,3 incl. ZERO-sample pixels).
//   * INCREASING_Y; owner(string)="exr-rs", parityTag(int)=31337.
//   * per-SAMPLE formula keyed on the level-relative pixel index pidx =
//     ly*levelWidth + lx and the sample index s in [0, N):
//       R = half(1.0 + pidx*0.5 + s*1.0),  G = half(100.0 + pidx*0.25 + s*2.0),
//       B = half(-50.0 + pidx*1.0 - s*1.0), Z = f32(pidx*100.0 + s*1.0).
//   * an OFF-ORIGIN scanline variant uses data window min = (-3, 7).  Because
//     the formula is level-relative, the on-disk bytes are identical for the
//     origin and off-origin variants (same property the tiled gate relies on).
//
// Scope: the C++ cross-read covers deep scanline (incl. off-origin) + deep
// tiled ONE_LEVEL for every valid deep codec (NONE/RLE/ZIPS), and deep tiled
// MIPMAP (the `*_mipmap_*` tests below), in BOTH directions.  Our deep
// flat-heap is a safe-Rust adaptation of C++'s `char**`, addressed in
// WHOLE-(level-0)-WINDOW raster order for every level (the writer gathers and
// the reader scatters every MIPMAP level from the SAME full-window count
// buffer); that contract is an API property, not an on-disk one.  Deep MIPMAP
// read/write is additionally covered (count+sample-exact, all levels) by the
// in-crate round-trip tests.

use exr_core::deep::{
    CompositeDeepScanLine, DeepFrameBuffer, DeepScanLineInputFile, DeepScanLineOutputFile,
    DeepSlice, DeepTiledInputFile, DeepTiledOutputFile,
};
use exr_core::header::{DEEP_SCANLINE, DEEP_TILE};
use exr_core::misc::pixel_type_size;

const DW: i32 = 8;
const DH: i32 = 6;
const DTILE: u32 = 4;

// --- KNOWN deep formulas (must equal oracle.cpp, byte-for-byte) ------------

/// Per-pixel sample count, keyed on LEVEL-relative coords.
fn deep_count(lx: i32, ly: i32) -> u32 {
    ((lx + ly) % 4) as u32
}
fn d_r_val(pidx: i32, s: i32) -> f32 { 1.0 + pidx as f32 * 0.5 + s as f32 }
fn d_g_val(pidx: i32, s: i32) -> f32 { 100.0 + pidx as f32 * 0.25 + s as f32 * 2.0 }
fn d_b_val(pidx: i32, s: i32) -> f32 { -50.0 + pidx as f32 - s as f32 }
fn d_z_val(pidx: i32, s: i32) -> f32 { pidx as f32 * 100.0 + s as f32 }

/// Expected sample bits for channel `chan` at level-relative pixel index `pidx`
/// and sample index `s` (HALF -> u16 in low bits, FLOAT -> u32).
fn d_expected_sample(chan: &str, pidx: i32, s: i32) -> (u64, bool) {
    match chan {
        "R" => (half_bits(d_r_val(pidx, s)) as u64, true),
        "G" => (half_bits(d_g_val(pidx, s)) as u64, true),
        "B" => (half_bits(d_b_val(pidx, s)) as u64, true),
        "Z" => (d_z_val(pidx, s).to_bits() as u64, false),
        other => panic!("unknown deep channel {other}"),
    }
}

/// The deep channel list in alphabetical (file) order: B,G,R (HALF), Z (FLOAT).
fn deep_channels() -> Vec<(&'static str, PixelType)> {
    vec![
        ("B", PixelType::Half),
        ("G", PixelType::Half),
        ("R", PixelType::Half),
        ("Z", PixelType::Float),
    ]
}

/// Build the KNOWN deep header for a `w x h` data window at `(min_x, min_y)`
/// with compression `comp`.  `tiled` adds the tile description + deeptile type;
/// otherwise it is a deepscanline header.
fn deep_header(
    w: i32,
    h: i32,
    min_x: i32,
    min_y: i32,
    comp: Compression,
    tiled: Option<(u32, LevelMode)>,
) -> Header {
    let mut hd = Header::with_dimensions(
        w,
        h,
        1.0,
        V2f { x: 0.0, y: 0.0 },
        1.0,
        LineOrder::IncreasingY,
        comp,
    )
    .unwrap();
    if min_x != 0 || min_y != 0 {
        let dw = Box2i::from_min_max(
            V2i { x: min_x, y: min_y },
            V2i { x: min_x + w - 1, y: min_y + h - 1 },
        );
        hd.insert("dataWindow", Box2iAttribute::new(dw)).unwrap();
        hd.insert("displayWindow", Box2iAttribute::new(dw)).unwrap();
    }
    let mut cl = ChannelList::new();
    for (name, ty) in deep_channels() {
        cl.insert(name, Channel::new(ty, 1, 1, false)).unwrap();
    }
    hd.insert("channels", ChannelListAttribute::new(cl)).unwrap();
    hd.insert("owner", StringAttribute::new(ExrString::from("exr-rs"))).unwrap();
    hd.insert("parityTag", IntAttribute::new(31337)).unwrap();
    if let Some((tile, mode)) = tiled {
        hd.insert(
            "tiles",
            TileDescriptionAttribute::new(TileDescription {
                x_size: tile,
                y_size: tile,
                mode,
                rounding_mode: LevelRoundingMode::RoundDown,
            }),
        )
        .unwrap();
        hd.set_type(DEEP_TILE).unwrap();
    } else {
        hd.set_type(DEEP_SCANLINE).unwrap();
    }
    hd
}

/// Build the flat per-pixel sample-count buffer (u32 LE per pixel), addressed
/// in ABSOLUTE window coords (`off = y*yStride + x*xStride`, xStride=4,
/// yStride=4*w), sized to the absolute extent `(min_y + h) * yStride`.  Counts
/// are by the level-relative formula.  Returns `(buf, x_stride, y_stride)`.
fn deep_count_buffer(w: i32, h: i32, min_x: i32, min_y: i32) -> (Vec<u8>, i32, i32) {
    let x_stride = 4i32;
    let y_stride = 4 * w;
    let total = ((min_y + h) as i64 * y_stride as i64) as usize;
    let mut sc = vec![0u8; total];
    for ly in 0..h {
        for lx in 0..w {
            let x = min_x + lx;
            let y = min_y + ly;
            let off = (y as i64 * y_stride as i64 + x as i64 * x_stride as i64) as usize;
            sc[off..off + 4].copy_from_slice(&deep_count(lx, ly).to_le_bytes());
        }
    }
    (sc, x_stride, y_stride)
}

/// Build a sample-count buffer for ONE MIPMAP level addressed in the
/// **level-0 (grid) raster order** that our deep tiled reader/writer use for
/// EVERY level (the "whole-window flat-heap" contract: the writer gathers and
/// the reader scatters every level from the same level-0 count buffer).  The buffer is `grid_w` wide (so its
/// strides match `samples_before_pixel`'s `max_x = grid_w - 1` addressing) but
/// only the level's `lw x lh` top-left corner carries counts; every pixel
/// outside the level rect is left at 0.  Because those out-of-level cells are
/// zero, `samples_before_pixel(lx, ly, 0, grid_w-1, 0)` collapses to the
/// level-LOCAL cumulative count (Σ over `lw`-wide rows), so it stays exactly
/// consistent with [`deep_sample_heap`]`(lw, lh)` (level-local raster order) —
/// which is what makes a per-level C++ KNOWN image addressable by our reader.
/// Counts follow the SAME `deep_count(lx, ly)` formula at every level (origin
/// only — MIPMAP variants are all origin).  Returns `(buf, x_stride, y_stride)`.
fn deep_count_buffer_mip(lw: i32, lh: i32, grid_w: i32) -> (Vec<u8>, i32, i32) {
    let x_stride = 4i32;
    let y_stride = 4 * grid_w;
    let total = (lh as i64 * y_stride as i64) as usize;
    let mut sc = vec![0u8; total];
    for ly in 0..lh {
        for lx in 0..lw {
            let off = (ly as i64 * y_stride as i64 + lx as i64 * x_stride as i64) as usize;
            sc[off..off + 4].copy_from_slice(&deep_count(lx, ly).to_le_bytes());
        }
    }
    (sc, x_stride, y_stride)
}

/// Build the flat per-channel sample heap (each channel contiguous in
/// whole-window raster order: line by line, x left-to-right, all samples of
/// each pixel) plus each channel's base offset into the heap.  This is the
/// exact layout the deep writer gathers from and the deep reader scatters into
/// (`samples_before_pixel` walks the same raster order).
fn deep_sample_heap(w: i32, h: i32) -> (Vec<u8>, Vec<i64>) {
    let mut heap = Vec::new();
    let mut bases = Vec::new();
    for (name, ty) in deep_channels() {
        bases.push(heap.len() as i64);
        for ly in 0..h {
            for lx in 0..w {
                let pidx = ly * w + lx;
                let n = deep_count(lx, ly) as i32;
                for s in 0..n {
                    match name {
                        "R" => heap.extend_from_slice(&half_bits(d_r_val(pidx, s)).to_le_bytes()),
                        "G" => heap.extend_from_slice(&half_bits(d_g_val(pidx, s)).to_le_bytes()),
                        "B" => heap.extend_from_slice(&half_bits(d_b_val(pidx, s)).to_le_bytes()),
                        "Z" => heap.extend_from_slice(&d_z_val(pidx, s).to_le_bytes()),
                        _ => unreachable!(),
                    }
                }
            }
        }
        let _ = ty;
    }
    (heap, bases)
}

/// Build the deep frame buffer (flat model): sample-count slice + one deep
/// slice per channel pointing at its base in the heap.  Deep slice strides are
/// the C++ pointer-slot strides (8 bytes/pointer): xStride=8, yStride=8*w,
/// sampleStride=type size.
fn deep_frame_buffer(w: i32, bases: &[i64], sc_x: i32, sc_y: i32) -> DeepFrameBuffer {
    let mut fb = DeepFrameBuffer::new();
    fb.insert_sample_count_slice(Slice {
        type_: PixelType::Uint,
        base_offset: 0,
        x_stride: sc_x as usize,
        y_stride: sc_y as usize,
        x_sampling: 1,
        y_sampling: 1,
        fill_value: 0.0,
        x_tile_coords: false,
        y_tile_coords: false,
    })
    .unwrap();
    for (ci, (name, ty)) in deep_channels().into_iter().enumerate() {
        let ss = pixel_type_size(ty).unwrap();
        fb.insert(
            name,
            DeepSlice::new(ty, bases[ci], 8, 8 * w as usize, ss, 1, 1, 0.0, false, false).unwrap(),
        )
        .unwrap();
    }
    fb
}

/// One decoded deep sample, keyed (level, chan, x, y, i) with x/y RELATIVE to
/// the level data-window min — the same key the oracle emits.
#[derive(Clone)]
struct DSampRec {
    level: i32,
    chan: String,
    x: i32,
    y: i32,
    i: i32,
    bits: u64,
    is_half: bool,
}

/// Parsed oracle deep-read output.
struct DeepRead {
    compression: i32,
    level_mode: i32,
    num_levels: i32,
    tile_x: u32,
    tile_y: u32,
    attrs: Vec<(String, String, String)>,
    /// (level, x, y) -> count, x/y relative to level min.
    counts: std::collections::HashMap<(i32, i32, i32), u32>,
    samples: Vec<DSampRec>,
}

/// Parse the oracle's `read-deep-scanline` / `read-deep-tiled` output.  The
/// scanline grammar uses COUNT/SAMP (implicit level 0); the tiled grammar uses
/// TILEDESC/LEVELMODE/NUMLEVELS/DCOUNT/DSAMP.
fn parse_oracle_deep(stdout: &str) -> DeepRead {
    let mut dr = DeepRead {
        compression: -1,
        level_mode: 0, // ONE_LEVEL default for scanline
        num_levels: 1,
        tile_x: 0,
        tile_y: 0,
        attrs: Vec::new(),
        counts: std::collections::HashMap::new(),
        samples: Vec::new(),
    };
    for line in stdout.lines() {
        let mut it = line.split_whitespace();
        match it.next() {
            Some("COMPRESSION") => dr.compression = it.next().unwrap().parse().unwrap(),
            Some("LEVELMODE") => dr.level_mode = it.next().unwrap().parse().unwrap(),
            Some("NUMLEVELS") => dr.num_levels = it.next().unwrap().parse().unwrap(),
            Some("TILEDESC") => {
                dr.tile_x = it.next().unwrap().parse().unwrap();
                dr.tile_y = it.next().unwrap().parse().unwrap();
            }
            Some("ATTR") => {
                let name = it.next().unwrap_or("").to_string();
                let ty = it.next().unwrap_or("").to_string();
                let val = it.collect::<Vec<_>>().join(" ");
                dr.attrs.push((name, ty, val));
            }
            Some("COUNT") => {
                let x: i32 = it.next().unwrap().parse().unwrap();
                let y: i32 = it.next().unwrap().parse().unwrap();
                let n: u32 = it.next().unwrap().parse().unwrap();
                dr.counts.insert((0, x, y), n);
            }
            Some("DCOUNT") => {
                let l: i32 = it.next().unwrap().parse().unwrap();
                let x: i32 = it.next().unwrap().parse().unwrap();
                let y: i32 = it.next().unwrap().parse().unwrap();
                let n: u32 = it.next().unwrap().parse().unwrap();
                dr.counts.insert((l, x, y), n);
            }
            Some("SAMP") => {
                let chan = it.next().unwrap().to_string();
                let x: i32 = it.next().unwrap().parse().unwrap();
                let y: i32 = it.next().unwrap().parse().unwrap();
                let i: i32 = it.next().unwrap().parse().unwrap();
                let hex = it.next().unwrap();
                let is_half = hex.len() == 4;
                let bits = u64::from_str_radix(hex, 16).unwrap();
                dr.samples.push(DSampRec { level: 0, chan, x, y, i, bits, is_half });
            }
            Some("DSAMP") => {
                let l: i32 = it.next().unwrap().parse().unwrap();
                let chan = it.next().unwrap().to_string();
                let x: i32 = it.next().unwrap().parse().unwrap();
                let y: i32 = it.next().unwrap().parse().unwrap();
                let i: i32 = it.next().unwrap().parse().unwrap();
                let hex = it.next().unwrap();
                let is_half = hex.len() == 4;
                let bits = u64::from_str_radix(hex, 16).unwrap();
                dr.samples.push(DSampRec { level: l, chan, x, y, i, bits, is_half });
            }
            _ => {}
        }
    }
    dr
}

/// Locate a committed deep golden by file name.
fn deep_golden(name: &str) -> PathBuf {
    parity_file(name)
}

// ---------------------------------------------------------------------------
// (a) C++ -> ours: read each committed deep golden with our reader; assert
//     per-pixel COUNTS exact AND every sample bit-exact vs the KNOWN formula.
// ---------------------------------------------------------------------------

/// Read a deep SCANLINE golden with OUR [`DeepScanLineInputFile`] and assert
/// counts + every sample match the KNOWN image.  `min_x/min_y` is the golden's
/// data-window origin (the off-origin variant uses (-3, 7)).
fn cpp_deep_scanline_read_by_ours(file: &str, comp: Compression, min_x: i32, min_y: i32) {
    let Some(golden) = support::fixture_or_skip(
        &format!("cpp_deep_scanline_read_by_ours({file})"),
        deep_golden(file),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };

    let mut is = StdIfStream::open(golden.to_str().unwrap()).expect("open deep scanline golden");
    let mut inf = DeepScanLineInputFile::new(&mut is).expect("DeepScanLineInputFile::new");
    assert_eq!(inf.header().type_().unwrap(), DEEP_SCANLINE, "{file}: not deepscanline");
    assert_eq!(inf.header().compression().unwrap(), comp, "{file}: compression mismatch");

    let (_sc, sc_x, sc_y) = deep_count_buffer(DW, DH, min_x, min_y);
    let (expected_heap, bases) = deep_sample_heap(DW, DH);
    let fb = deep_frame_buffer(DW, &bases, sc_x, sc_y);
    inf.set_frame_buffer(&fb).unwrap();

    // Pass 1: counts into a fresh zeroed buffer (absolute extent).
    let total = ((min_y + DH) as i64 * sc_y as i64) as usize;
    let mut counts_buf = vec![0u8; total];
    inf.read_pixel_sample_counts(min_y, min_y + DH - 1, &mut counts_buf).unwrap();
    for ly in 0..DH {
        for lx in 0..DW {
            let x = min_x + lx;
            let y = min_y + ly;
            let off = (y as i64 * sc_y as i64 + x as i64 * sc_x as i64) as usize;
            let got = u32::from_le_bytes(counts_buf[off..off + 4].try_into().unwrap());
            assert_eq!(got, deep_count(lx, ly), "{file}: count mismatch at ({lx},{ly})");
        }
    }

    // Pass 2: samples into a fresh zeroed heap sized like the writer's.
    let mut heap = vec![0u8; expected_heap.len()];
    inf.read_pixels(min_y, min_y + DH - 1, &counts_buf, &mut heap).unwrap();
    assert_eq!(heap, expected_heap, "{file}: deep sample data not bit-exact vs KNOWN");
    eprintln!("OK (a-deep {file}) ours read counts + {} sample bytes bit-exact vs KNOWN.", heap.len());
}

#[test]
fn cpp_deep_scanline_none_read_by_ours() {
    cpp_deep_scanline_read_by_ours("golden_deep_scanline_none.exr", Compression::NoCompression, 0, 0);
}
#[test]
fn cpp_deep_scanline_rle_read_by_ours() {
    cpp_deep_scanline_read_by_ours("golden_deep_scanline_rle.exr", Compression::Rle, 0, 0);
}
#[test]
fn cpp_deep_scanline_zips_read_by_ours() {
    cpp_deep_scanline_read_by_ours("golden_deep_scanline_zips.exr", Compression::Zips, 0, 0);
}
#[test]
fn cpp_deep_scanline_none_offset_read_by_ours() {
    cpp_deep_scanline_read_by_ours("golden_deep_scanline_none_offset.exr", Compression::NoCompression, -3, 7);
}

// ---------------------------------------------------------------------------
// CompositeDeepScanLine oracle gate.
//
// `golden_deep_composite_a.exr` / `_b.exr` are TWO real C++-written deep
// scanline sources (`oracle.cpp::do_write_deep_composite`) with overlapping,
// interleaved Z ranges at some pixels (forcing a real cross-source sort),
// pixels where only ONE source has samples (forcing `num_sources == 1`
// despite 2 configured sources), and multi-sample-per-pixel accumulation
// (every sample's alpha keeps the running total < 1, so the full
// accumulate loop runs, never early-exiting).
//
// `golden_deep_composite.dump` is the REAL C++ `CompositeDeepScanLine`
// (default `DeepCompositing`) result, dumped as hex float bits
// (`oracle.cpp::do_composite_deep_scanline`). This test reads BOTH goldens
// with OUR `DeepScanLineInputFile` (already proven byte/sample-exact
// elsewhere in this file) and composites them with OUR
// `CompositeDeepScanLine`, then asserts the result is BIT-EXACT against the
// real C++ dump -- the one thing not already covered by the existing deep
// read/write parity tests: the sort + front-to-back accumulation MATH
// itself.
#[test]
fn cpp_composite_deep_scanline_bit_exact() {
    let Some(golden_a) = support::fixture_or_skip(
        "cpp_composite_deep_scanline_bit_exact",
        deep_golden("golden_deep_composite_a.exr"),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };
    let golden_b = deep_golden("golden_deep_composite_b.exr");
    let dump_path = deep_golden("golden_deep_composite.dump");

    // Parse the oracle's dump: "DIM w h" then "PIX x y CHAN hexbits" lines.
    let dump_text = std::fs::read_to_string(&dump_path)
        .unwrap_or_else(|e| panic!("reading {}: {e}", dump_path.display()));
    let mut lines = dump_text.lines();
    let dim_line = lines.next().expect("dump missing DIM line");
    let mut dim_it = dim_line.split_whitespace();
    assert_eq!(dim_it.next(), Some("DIM"));
    let w: i32 = dim_it.next().unwrap().parse().unwrap();
    let h: i32 = dim_it.next().unwrap().parse().unwrap();

    let mut expected: std::collections::HashMap<(i32, i32, &'static str), u32> = Default::default();
    for line in lines {
        if line == "END" {
            break;
        }
        let mut it = line.split_whitespace();
        assert_eq!(it.next(), Some("PIX"));
        let x: i32 = it.next().unwrap().parse().unwrap();
        let y: i32 = it.next().unwrap().parse().unwrap();
        let chan = match it.next().unwrap() {
            "Z" => "Z",
            "A" => "A",
            "R" => "R",
            other => panic!("unexpected channel {other} in dump"),
        };
        let bits = u32::from_str_radix(it.next().unwrap(), 16).unwrap();
        expected.insert((x, y, chan), bits);
    }

    // Read both sources with OUR reader and composite with OUR CompositeDeepScanLine.
    let mut is_a = StdIfStream::open(golden_a.to_str().unwrap()).expect("open composite source a");
    let mut src_a = DeepScanLineInputFile::new(&mut is_a).expect("DeepScanLineInputFile a");
    let mut is_b = StdIfStream::open(golden_b.to_str().unwrap()).expect("open composite source b");
    let mut src_b = DeepScanLineInputFile::new(&mut is_b).expect("DeepScanLineInputFile b");

    let mut comp = CompositeDeepScanLine::new();
    comp.add_source(&mut src_a).unwrap();
    comp.add_source(&mut src_b).unwrap();

    let dw = comp.data_window();
    assert_eq!(dw.max.x - dw.min.x + 1, w, "data window width mismatch vs dump");
    assert_eq!(dw.max.y - dw.min.y + 1, h, "data window height mismatch vs dump");

    // Interleaved Z, A, R output (matches the oracle's flat layout closely
    // enough -- addressing is independent per slice regardless of order).
    let mut fb = FrameBuffer::new();
    fb.insert(
        "Z",
        Slice { type_: PixelType::Float, base_offset: 0, x_stride: 4, y_stride: 4 * w as usize, x_sampling: 1, y_sampling: 1, fill_value: 0.0, x_tile_coords: false, y_tile_coords: false },
    ).unwrap();
    fb.insert(
        "A",
        Slice { type_: PixelType::Float, base_offset: 4 * w as i64 * h as i64, x_stride: 4, y_stride: 4 * w as usize, x_sampling: 1, y_sampling: 1, fill_value: 0.0, x_tile_coords: false, y_tile_coords: false },
    ).unwrap();
    fb.insert(
        "R",
        Slice { type_: PixelType::Float, base_offset: 8 * w as i64 * h as i64, x_stride: 4, y_stride: 4 * w as usize, x_sampling: 1, y_sampling: 1, fill_value: 0.0, x_tile_coords: false, y_tile_coords: false },
    ).unwrap();
    comp.set_frame_buffer(&fb).unwrap();

    let mut out = vec![0u8; 3 * w as usize * h as usize * 4];
    comp.read_pixels(dw.min.y, dw.max.y, &mut out).unwrap();

    let plane = w as usize * h as usize * 4;
    let mut mismatches = 0usize;
    for y in dw.min.y..=dw.max.y {
        for x in dw.min.x..=dw.max.x {
            let px = (y - dw.min.y) as usize * w as usize + (x - dw.min.x) as usize;
            for (chan, plane_idx) in [("Z", 0usize), ("A", 1), ("R", 2)] {
                let off = plane_idx * plane + px * 4;
                let bits = u32::from_le_bytes(out[off..off + 4].try_into().unwrap());
                let want = *expected.get(&(x, y, chan)).unwrap_or_else(|| {
                    panic!("dump missing PIX {x} {y} {chan}")
                });
                if bits != want {
                    mismatches += 1;
                    eprintln!(
                        "MISMATCH ({x},{y}) {chan}: ours={bits:08x} ({}) cpp={want:08x} ({})",
                        f32::from_bits(bits), f32::from_bits(want)
                    );
                }
            }
        }
    }
    assert_eq!(mismatches, 0, "CompositeDeepScanLine output not bit-exact vs real C++ (see MISMATCH lines above)");
    eprintln!("OK (composite-deep-scanline) {w}x{h} composited output bit-exact vs real C++ CompositeDeepScanLine.");
}

// ---------------------------------------------------------------------------
// The GENERIC, real `Imf::InputFile` flattening a deep-scanline source
// oracle gate.
//
// `golden_deep_composite_a.exr.dump` is the real, GENERIC `Imf::InputFile`
// (not `DeepScanLineInputFile` directly) opening `golden_deep_composite_a.exr`
// (the single-source deep scanline fixture from the composite gate above, reused
// here), setting a flat Z/A/R `FrameBuffer`, calling `readPixels`, and
// dumping the flattened result as hex float bits
// (`oracle.cpp::do_read_deep_via_inputfile`). C++'s generic `InputFile`
// internally builds exactly the `DeepScanLineInputFile` +
// `CompositeDeepScanLine` pair the composite gate drives directly
// (`ImfInputFile.cpp:300-305`) -- this test instead goes through OUR
// `scanline::InputFile` (its `Reader::Deep` flatten path) and asserts the
// result is bit-exact against the real C++ generic-reader dump (internal
// consistency against `CompositeDeepScanLine` was already proven by a unit
// test; this is the missing literal comparison against C++'s `InputFile`).
#[test]
fn cpp_input_file_flattens_deep_scanline_bit_exact() {
    let Some(golden) = support::fixture_or_skip(
        "cpp_input_file_flattens_deep_scanline_bit_exact",
        deep_golden("golden_deep_composite_a.exr"),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };
    let dump_path = deep_golden("golden_deep_composite_a.exr.dump");

    // Parse the oracle's dump: "DIM w h" then "PIX x y CHAN hexbits" lines --
    // the exact same grammar `cpp_composite_deep_scanline_bit_exact` parses.
    let dump_text = std::fs::read_to_string(&dump_path)
        .unwrap_or_else(|e| panic!("reading {}: {e}", dump_path.display()));
    let mut lines = dump_text.lines();
    let dim_line = lines.next().expect("dump missing DIM line");
    let mut dim_it = dim_line.split_whitespace();
    assert_eq!(dim_it.next(), Some("DIM"));
    let w: i32 = dim_it.next().unwrap().parse().unwrap();
    let h: i32 = dim_it.next().unwrap().parse().unwrap();

    let mut expected: std::collections::HashMap<(i32, i32, &'static str), u32> = Default::default();
    for line in lines {
        if line == "END" {
            break;
        }
        let mut it = line.split_whitespace();
        assert_eq!(it.next(), Some("PIX"));
        let x: i32 = it.next().unwrap().parse().unwrap();
        let y: i32 = it.next().unwrap().parse().unwrap();
        let chan = match it.next().unwrap() {
            "Z" => "Z",
            "A" => "A",
            "R" => "R",
            other => panic!("unexpected channel {other} in dump"),
        };
        let bits = u32::from_str_radix(it.next().unwrap(), 16).unwrap();
        expected.insert((x, y, chan), bits);
    }

    // Read with OUR generic `InputFile` (its deep-scanline flatten path),
    // not `DeepScanLineInputFile` directly -- this is the whole point of the
    // gate.
    let mut is = StdIfStream::open(golden.to_str().unwrap()).expect("open deep composite source a");
    let mut inf = InputFile::new(&mut is).expect("InputFile::new on a deep-scanline part");

    let dw = inf.header().data_window().expect("data window");
    assert_eq!(dw.max.x - dw.min.x + 1, w, "data window width mismatch vs dump");
    assert_eq!(dw.max.y - dw.min.y + 1, h, "data window height mismatch vs dump");

    let mut fb = FrameBuffer::new();
    fb.insert(
        "Z",
        Slice { type_: PixelType::Float, base_offset: 0, x_stride: 4, y_stride: 4 * w as usize, x_sampling: 1, y_sampling: 1, fill_value: 0.0, x_tile_coords: false, y_tile_coords: false },
    ).unwrap();
    fb.insert(
        "A",
        Slice { type_: PixelType::Float, base_offset: 4 * w as i64 * h as i64, x_stride: 4, y_stride: 4 * w as usize, x_sampling: 1, y_sampling: 1, fill_value: 0.0, x_tile_coords: false, y_tile_coords: false },
    ).unwrap();
    fb.insert(
        "R",
        Slice { type_: PixelType::Float, base_offset: 8 * w as i64 * h as i64, x_stride: 4, y_stride: 4 * w as usize, x_sampling: 1, y_sampling: 1, fill_value: 0.0, x_tile_coords: false, y_tile_coords: false },
    ).unwrap();
    inf.set_frame_buffer(&fb).unwrap();

    let mut out = vec![0u8; 3 * w as usize * h as usize * 4];
    inf.read_pixels(dw.min.y, dw.max.y, &mut out).unwrap();

    let plane = w as usize * h as usize * 4;
    let mut mismatches = 0usize;
    for y in dw.min.y..=dw.max.y {
        for x in dw.min.x..=dw.max.x {
            let px = (y - dw.min.y) as usize * w as usize + (x - dw.min.x) as usize;
            for (chan, plane_idx) in [("Z", 0usize), ("A", 1), ("R", 2)] {
                let off = plane_idx * plane + px * 4;
                let bits = u32::from_le_bytes(out[off..off + 4].try_into().unwrap());
                let want = *expected.get(&(x, y, chan)).unwrap_or_else(|| {
                    panic!("dump missing PIX {x} {y} {chan}")
                });
                if bits != want {
                    mismatches += 1;
                    eprintln!(
                        "MISMATCH ({x},{y}) {chan}: ours={bits:08x} ({}) cpp={want:08x} ({})",
                        f32::from_bits(bits), f32::from_bits(want)
                    );
                }
            }
        }
    }
    assert_eq!(mismatches, 0, "InputFile deep-scanline flatten not bit-exact vs real C++ Imf::InputFile (see MISMATCH lines above)");
    eprintln!("OK (read-deep-via-inputfile) {w}x{h} InputFile-flattened deep scanline bit-exact vs real C++ Imf::InputFile.");
}

/// Read a deep TILED golden with OUR [`DeepTiledInputFile`] and assert counts +
/// every sample of every level match the KNOWN image.
fn cpp_deep_tiled_read_by_ours(file: &str, comp: Compression, mode: LevelMode) {
    let Some(golden) = support::fixture_or_skip(
        &format!("cpp_deep_tiled_read_by_ours({file})"),
        deep_golden(file),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };

    let mut is = StdIfStream::open(golden.to_str().unwrap()).expect("open deep tiled golden");
    let mut inf = DeepTiledInputFile::new(&mut is).expect("DeepTiledInputFile::new");
    assert_eq!(inf.header().type_().unwrap(), DEEP_TILE, "{file}: not deeptile");
    assert_eq!(inf.compression().unwrap(), comp, "{file}: compression mismatch");
    assert_eq!(inf.tile_x_size(), DTILE, "{file}: tileX mismatch");
    assert_eq!(inf.tile_y_size(), DTILE, "{file}: tileY mismatch");
    assert_eq!(inf.level_mode(), mode, "{file}: level mode mismatch");

    // Level-0 (grid) width: our deep tiled reader addresses the flat heap of
    // EVERY level in this whole-(level-0)-window raster order (`samples_before
    // _pixel` is always called with the level-0 window bounds).  So the per-level count buffer is
    // DW wide with counts only in the level's `lw x lh` corner; the zero cells
    // outside the level collapse `samples_before_pixel` to the level-LOCAL
    // cumulative count, keeping it consistent with `deep_sample_heap(lw, lh)`.
    let l0 = inf.data_window_for_level(0, 0).unwrap();
    let grid_w = l0.max.x - l0.min.x + 1;

    let num_levels = inf.num_levels().unwrap();
    for (lx_lvl, ly_lvl) in tiled_levels(mode, num_levels) {
        let lvl = inf.data_window_for_level(lx_lvl, ly_lvl).unwrap();
        let lw = lvl.max.x - lvl.min.x + 1;
        let lh = lvl.max.y - lvl.min.y + 1;

        let (_sc, sc_x, sc_y) = deep_count_buffer_mip(lw, lh, grid_w);
        let (expected_heap, bases) = deep_sample_heap(lw, lh);
        let fb = deep_frame_buffer(grid_w, &bases, sc_x, sc_y);
        inf.set_frame_buffer(&fb).unwrap();

        let nx = inf.num_x_tiles(lx_lvl).unwrap();
        let ny = inf.num_y_tiles(ly_lvl).unwrap();

        // Pass 1: counts into the level's DW-wide buffer (level-relative coords).
        let total = (lh as i64 * sc_y as i64) as usize;
        let mut counts_buf = vec![0u8; total];
        inf.read_pixel_sample_counts(0, nx - 1, 0, ny - 1, lx_lvl, ly_lvl, &mut counts_buf)
            .unwrap();
        for ly in 0..lh {
            for lx in 0..lw {
                let off = (ly as i64 * sc_y as i64 + lx as i64 * sc_x as i64) as usize;
                let got = u32::from_le_bytes(counts_buf[off..off + 4].try_into().unwrap());
                assert_eq!(
                    got,
                    deep_count(lx, ly),
                    "{file}: L({lx_lvl},{ly_lvl}) count mismatch at ({lx},{ly})"
                );
            }
        }

        // Pass 2: samples (level-local heap).
        let mut heap = vec![0u8; expected_heap.len()];
        inf.read_tiles(0, nx - 1, 0, ny - 1, lx_lvl, ly_lvl, &counts_buf, &mut heap)
            .unwrap();
        assert_eq!(
            heap, expected_heap,
            "{file}: L({lx_lvl},{ly_lvl}) deep sample data not bit-exact vs KNOWN"
        );
        eprintln!(
            "OK (a-deep {file}) L({lx_lvl},{ly_lvl}) {lw}x{lh}: counts + {} sample bytes bit-exact vs KNOWN.",
            heap.len()
        );
    }
}

