// ---------------------------------------------------------------------------
// (b) ours -> C++: our deep writer writes the KNOWN image; the C++ oracle reads
//     it back and we assert every count + sample + metadata exactly.
// ---------------------------------------------------------------------------

/// Run the oracle in a deep-read mode and parse it.
fn oracle_read_deep(oracle: &Path, mode: &str, path: &Path) -> DeepRead {
    let output = Command::new(oracle)
        .arg(mode)
        .arg(path)
        .output()
        .expect("failed to run oracle deep read");
    let stdout = String::from_utf8_lossy(&output.stdout);
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(
        output.status.success(),
        "oracle {mode} failed (status {}):\nstderr:\n{stderr}",
        output.status
    );
    parse_oracle_deep(&stdout)
}

/// Assert the deep read carries the KNOWN owner/parityTag.
fn assert_deep_attrs(dr: &DeepRead, file: &str) {
    let owner = dr.attrs.iter().find(|(n, ..)| n == "owner");
    assert_eq!(
        owner.map(|(_, t, v)| (t.as_str(), v.as_str())),
        Some(("string", "exr-rs")),
        "{file}: owner attr mismatch: {:?}",
        dr.attrs
    );
    let tag = dr.attrs.iter().find(|(n, ..)| n == "parityTag");
    assert_eq!(
        tag.map(|(_, t, v)| (t.as_str(), v.as_str())),
        Some(("int", "31337")),
        "{file}: parityTag attr mismatch: {:?}",
        dr.attrs
    );
}

/// Assert a parsed deep read's counts + samples for ONE level (`lw x lh`,
/// level-relative formula) match the KNOWN image exactly.
fn assert_deep_level_known(dr: &DeepRead, level: i32, lw: i32, lh: i32, file: &str) {
    let mut expected_samples = 0usize;
    for ly in 0..lh {
        for lx in 0..lw {
            let got = dr.counts.get(&(level, lx, ly)).copied();
            assert_eq!(
                got,
                Some(deep_count(lx, ly)),
                "{file}: L{level} count mismatch at ({lx},{ly})"
            );
            for _ in 0..deep_count(lx, ly) {
                expected_samples += 4; // R,G,B,Z
            }
        }
    }
    for rec in dr.samples.iter().filter(|r| r.level == level) {
        let pidx = rec.y * lw + rec.x;
        let (bits, is_half) = d_expected_sample(&rec.chan, pidx, rec.i);
        assert_eq!(rec.is_half, is_half, "{file}: L{level} chan {} bit-width", rec.chan);
        assert_eq!(
            rec.bits, bits,
            "{file}: L{level} divergent sample bits for chan {} at ({},{}) i={}",
            rec.chan, rec.x, rec.y, rec.i
        );
    }
    let got_samples = dr.samples.iter().filter(|r| r.level == level).count();
    assert_eq!(got_samples, expected_samples, "{file}: L{level} sample COUNT mismatch");
}

/// Write the KNOWN deep scanline image with OUR writer; the C++ oracle reads it
/// back; assert metadata + every count + sample.
fn ours_write_deep_scanline_read_by_cpp(tmp: &str, comp: Compression, min_x: i32, min_y: i32) {
    let Some(oracle) = support::oracle_or_skip(tmp) else { return };

    let out_path = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(tmp);
    {
        let header = deep_header(DW, DH, min_x, min_y, comp, None);
        let (sc, sc_x, sc_y) = deep_count_buffer(DW, DH, min_x, min_y);
        let (heap, bases) = deep_sample_heap(DW, DH);
        let fb = deep_frame_buffer(DW, &bases, sc_x, sc_y);
        let mut os = StdOfStreamWrap::create(out_path.to_str().unwrap());
        let mut df = DeepScanLineOutputFile::new(&mut os.0, &header).unwrap();
        df.set_frame_buffer(&fb).unwrap();
        df.write_pixels(&sc, &heap, DH).unwrap();
    }

    let dr = oracle_read_deep(&oracle, "read-deep-scanline", &out_path);
    assert_eq!(dr.compression, comp as i32, "{tmp}: compression mismatch");
    assert_deep_attrs(&dr, tmp);
    assert_deep_level_known(&dr, 0, DW, DH, tmp);
    eprintln!("OK (b-deep {tmp}) ours -> C++ oracle: counts + all samples read back bit-exact.");
}

