/// Write the KNOWN deep tiled image with OUR writer; the C++ oracle reads it
/// back; assert metadata + every count + sample of EVERY level (ONE_LEVEL +
/// MIPMAP).  For MIPMAP we set a fresh per-level frame buffer (DW-wide count
/// buffer with counts only in the level's corner + a level-local sample heap)
/// and write that level's tiles, exactly mirroring the oracle's per-level
/// `do_write_deep_tiled` loop (our writer gathers every level from a level-0
/// strided count buffer, so the level's counts sit in its top-left corner).
fn ours_write_deep_tiled_read_by_cpp(tmp: &str, comp: Compression, mode: LevelMode) {
    let Some(oracle) = support::oracle_or_skip(tmp) else { return };

    let out_path = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join(tmp);
    let header = deep_header(DW, DH, 0, 0, comp, Some((DTILE, mode)));
    {
        let mut os = StdOfStreamWrap::create(out_path.to_str().unwrap());
        let mut df = DeepTiledOutputFile::new(&mut os.0, &header).unwrap();
        let grid_w = df.level_width(0).unwrap(); // level-0 width = whole-window stride
        let num_levels = df.num_levels().unwrap();
        // Pixel data is passed PER WRITE CALL: `set_frame_buffer`
        // stores only the layout; each level's fresh count/sample bytes are
        // passed straight to that level's `write_tiles` call.
        for (lx_lvl, ly_lvl) in tiled_levels(mode, num_levels) {
            let lw = df.level_width(lx_lvl).unwrap();
            let lh = df.level_height(ly_lvl).unwrap();
            let (sc, sc_x, sc_y) = deep_count_buffer_mip(lw, lh, grid_w);
            let (heap, bases) = deep_sample_heap(lw, lh);
            let fb = deep_frame_buffer(grid_w, &bases, sc_x, sc_y);
            df.set_frame_buffer(&fb).unwrap();
            let nx = df.num_x_tiles(lx_lvl).unwrap();
            let ny = df.num_y_tiles(ly_lvl).unwrap();
            df.write_tiles(&sc, &heap, 0, nx - 1, 0, ny - 1, lx_lvl, ly_lvl).unwrap();
        }
    }

    let dr = oracle_read_deep(&oracle, "read-deep-tiled", &out_path);
    assert_eq!(dr.compression, comp as i32, "{tmp}: compression mismatch");
    assert_eq!(dr.tile_x, DTILE, "{tmp}: tileX mismatch");
    assert_eq!(dr.tile_y, DTILE, "{tmp}: tileY mismatch");
    assert_eq!(dr.level_mode, mode as i32, "{tmp}: level mode mismatch");
    assert_deep_attrs(&dr, tmp);

    // Assert every level the oracle reported back, level-LOCAL `lw x lh`.
    let levels = match mode {
        LevelMode::OneLevel => vec![(0i32, DW, DH)],
        LevelMode::MipmapLevels => (0..dr.num_levels)
            .map(|l| {
                let lw = (DW >> l).max(1);
                let lh = (DH >> l).max(1);
                (l, lw, lh)
            })
            .collect(),
        _ => unreachable!("deep tiled gate covers ONE_LEVEL + MIPMAP only"),
    };
    for (level, lw, lh) in levels {
        assert_deep_level_known(&dr, level, lw, lh, tmp);
    }
    eprintln!("OK (b-deep {tmp}) ours -> C++ oracle: counts + all samples of all levels read back bit-exact.");
}

