// ###########################################################################
// # MULTIPART parity gate
// #
// # Proves our MultiPart read/write + the typed Part wrappers interoperate
// # with a real C++ OpenEXR (vcpkg OpenEXR-3_4) in BOTH directions, on ONE
// # file holding THREE MIXED-type parts (all LOSSLESS codecs -> bit-exact):
// #
// #   part | type           | codec | name
// #   -----+----------------+-------+--------
// #    0   | scanlineimage  | NONE  | "rgba"
// #    1   | tiledimage     | ZIP   | "tiled"
// #    2   | deepscanline   | ZIPS  | "deep"
// #
// # (a) C++ -> ours: our MultiPartInputFile + the *InputPart wrappers read the
// #     committed golden_multipart.exr; assert numParts, each part's type/name,
// #     and every pixel/count/sample bit-exact vs the KNOWN formula.
// # (b) ours -> C++: our MultiPartOutputFile + the *OutputPart wrappers write
// #     the KNOWN file; the oracle `read-multipart` reads it; assert C++ sees
// #     numParts + every part's pixels/counts/samples + metadata exactly.
// #     Gated on EXR_ORACLE_EXE (skip-with-note standalone).
// #
// # The KNOWN image (defined ONCE here, identical to oracle.cpp):
// #   * geometry MPW x MPH = 8 x 6 at origin, INCREASING_Y; tiled part uses a
// #     4x4 ONE_LEVEL/ROUND_DOWN tile -> 2x2 tiles (partial bottom row).
// #   * flat parts: R,G,B = HALF, Z = FLOAT (stored alphabetically as B,G,R,Z);
// #     deep part: same channels, VARIABLE counts N(x,y) = (x+y)%4.
// #   * flat per-pixel (idx = y*MPW + x, per-part bias pbias = part*1000):
// #       R = half(1.0 + (idx+pbias)*0.5), G = half(100.0 + idx*0.25 + pbias),
// #       B = half(-50.0 + idx*1.0 - pbias), Z = f32(idx*100.0 + pbias).
// #   * deep per-sample (idx, s in [0,N)):
// #       R = half(1.0 + idx*0.5 + s), G = half(100.0 + idx*0.25 + s*2),
// #       B = half(-50.0 + idx*1.0 - s), Z = f32(idx*100.0 + s).
// #   * header extras on EVERY part: owner(string)="exr-rs", parityTag(int)=31337.
// ###########################################################################

mod multipart_gate {
    use super::{float_bits, half_bits};
    use exr_core::attr::tile_description::{LevelMode, LevelRoundingMode};
    use exr_core::attr::{
        Channel, ChannelList, ChannelListAttribute, Compression, ExrString, LineOrder, PixelType,
        TileDescription, TileDescriptionAttribute,
    };
    use exr_core::deep::frame_buffer::DeepSlice;
    use exr_core::deep::DeepFrameBuffer;
    use exr_core::frame_buffer::{FrameBuffer, Slice};
    use exr_core::header::{Header, DEEP_SCANLINE, SCANLINE_IMAGE, TILED_IMAGE};
    use exr_core::misc::pixel_type_size;
    use exr_core::multipart::{MultiPartInputFile, MultiPartOutputFile};
    use exr_core::{IntAttribute, MemIStream, MemOStream, StringAttribute};
    use imath_rs::V2f;
    use std::path::{Path, PathBuf};
    use std::process::Command;

    const MPW: i32 = 8;
    const MPH: i32 = 6;
    const MP_TILE: u32 = 4;

    // --- KNOWN flat per-pixel formulas (must equal oracle.cpp) -------------
    fn r_val(idx: i32, pbias: i32) -> f32 { 1.0 + (idx + pbias) as f32 * 0.5 }
    fn g_val(idx: i32, pbias: i32) -> f32 { 100.0 + idx as f32 * 0.25 + pbias as f32 }
    fn b_val(idx: i32, pbias: i32) -> f32 { -50.0 + idx as f32 * 1.0 - pbias as f32 }
    fn z_val(idx: i32, pbias: i32) -> f32 { idx as f32 * 100.0 + pbias as f32 }

    // --- KNOWN deep per-sample formulas (must equal oracle.cpp) ------------
    fn deep_count(x: i32, y: i32) -> i32 { (x + y) % 4 }
    fn d_r_val(idx: i32, s: i32) -> f32 { 1.0 + idx as f32 * 0.5 + s as f32 }
    fn d_g_val(idx: i32, s: i32) -> f32 { 100.0 + idx as f32 * 0.25 + s as f32 * 2.0 }
    fn d_b_val(idx: i32, s: i32) -> f32 { -50.0 + idx as f32 * 1.0 - s as f32 }
    fn d_z_val(idx: i32, s: i32) -> f32 { idx as f32 * 100.0 + s as f32 }

    /// Interleaved flat layout: [R half][G half][B half][Z f32] = 8 bytes/pixel.
    const FLAT_PIXEL_BYTES: usize = 2 + 2 + 2 + 4;

    fn flat_chan_offset(name: &str) -> usize {
        match name { "R" => 0, "G" => 2, "B" => 4, "Z" => 6, _ => unreachable!() }
    }

    /// Build the interleaved flat pixel buffer for a part (per-part bias).
    fn flat_pixels(pbias: i32) -> Vec<u8> {
        let row_bytes = FLAT_PIXEL_BYTES * MPW as usize;
        let mut buf = vec![0u8; row_bytes * MPH as usize];
        for y in 0..MPH {
            for x in 0..MPW {
                let idx = y * MPW + x;
                let p = y as usize * row_bytes + x as usize * FLAT_PIXEL_BYTES;
                buf[p..p + 2].copy_from_slice(&half_bits(r_val(idx, pbias)).to_ne_bytes());
                buf[p + 2..p + 4].copy_from_slice(&half_bits(g_val(idx, pbias)).to_ne_bytes());
                buf[p + 4..p + 6].copy_from_slice(&half_bits(b_val(idx, pbias)).to_ne_bytes());
                buf[p + 6..p + 10].copy_from_slice(&z_val(idx, pbias).to_ne_bytes());
            }
        }
        buf
    }

    fn flat_frame_buffer() -> FrameBuffer {
        let row_bytes = FLAT_PIXEL_BYTES * MPW as usize;
        let mut fb = FrameBuffer::new();
        let mk = |ty: PixelType, off: usize| Slice {
            type_: ty,
            base_offset: off as i64,
            x_stride: FLAT_PIXEL_BYTES,
            y_stride: row_bytes,
            x_sampling: 1,
            y_sampling: 1,
            fill_value: 0.0,
            x_tile_coords: false,
            y_tile_coords: false,
        };
        fb.insert("R", mk(PixelType::Half, flat_chan_offset("R"))).unwrap();
        fb.insert("G", mk(PixelType::Half, flat_chan_offset("G"))).unwrap();
        fb.insert("B", mk(PixelType::Half, flat_chan_offset("B"))).unwrap();
        fb.insert("Z", mk(PixelType::Float, flat_chan_offset("Z"))).unwrap();
        fb
    }

    fn assert_flat_buffer_is_known(buf: &[u8], pbias: i32, what: &str) {
        let row_bytes = FLAT_PIXEL_BYTES * MPW as usize;
        for y in 0..MPH {
            for x in 0..MPW {
                let idx = y * MPW + x;
                let p = y as usize * row_bytes + x as usize * FLAT_PIXEL_BYTES;
                let r = u16::from_ne_bytes([buf[p], buf[p + 1]]);
                let g = u16::from_ne_bytes([buf[p + 2], buf[p + 3]]);
                let b = u16::from_ne_bytes([buf[p + 4], buf[p + 5]]);
                let z = u32::from_ne_bytes([buf[p + 6], buf[p + 7], buf[p + 8], buf[p + 9]]);
                assert_eq!(r, half_bits(r_val(idx, pbias)), "{what} R at ({x},{y})");
                assert_eq!(g, half_bits(g_val(idx, pbias)), "{what} G at ({x},{y})");
                assert_eq!(b, half_bits(b_val(idx, pbias)), "{what} B at ({x},{y})");
                assert_eq!(z, float_bits(z_val(idx, pbias)), "{what} Z at ({x},{y})");
            }
        }
    }

    // --- Deep part buffers ------------------------------------------------
    // Our deep model (src/deep) addresses, PER CHANNEL, a flat contiguous
    // sample heap: a sample's byte address is
    //   base_offset + samples_before_pixel(x,y) * sample_stride + i * sample_stride
    // where `samples_before_pixel` is the per-channel cumulative sample count
    // and `sample_stride` is the channel element size.  So each channel owns a
    // contiguous run of `total_samples` samples (raster order); we concatenate
    // the four channel heaps into one buffer and point each DeepSlice's
    // `base_offset` at its sub-heap start.  Heap layout: [R..][G..][B..][Z..].

    /// The flat u32-LE sample-count buffer (raster order, x_stride 4).
    fn deep_count_buffer() -> Vec<u8> {
        let row_bytes = 4 * MPW as usize;
        let mut sc = vec![0u8; row_bytes * MPH as usize];
        for y in 0..MPH {
            for x in 0..MPW {
                let off = y as usize * row_bytes + x as usize * 4;
                let n = deep_count(x, y) as u32;
                sc[off..off + 4].copy_from_slice(&n.to_ne_bytes());
            }
        }
        sc
    }

    /// Total samples across the whole image (sum of all per-pixel counts).
    fn total_samples() -> i32 {
        let mut t = 0;
        for y in 0..MPH { for x in 0..MPW { t += deep_count(x, y); } }
        t
    }

    /// Per-channel sub-heap byte sizes for the [R][G][B][Z] concatenated heap.
    fn deep_sub_offsets() -> (i64, i64, i64, i64, usize) {
        let ns = total_samples() as usize;
        let r0 = 0i64;
        let g0 = (ns * 2) as i64;
        let b0 = (ns * 4) as i64;
        let z0 = (ns * 6) as i64;
        let total = ns * (2 + 2 + 2 + 4);
        (r0, g0, b0, z0, total)
    }

    /// Build the concatenated per-channel sample heap [R half][G half][B half]
    /// [Z f32], each channel contiguous in raster order.
    fn deep_heap() -> Vec<u8> {
        let (r0, g0, b0, z0, total) = deep_sub_offsets();
        let mut heap = vec![0u8; total];
        let (mut ri, mut gi, mut bi, mut zi) =
            (r0 as usize, g0 as usize, b0 as usize, z0 as usize);
        for y in 0..MPH {
            for x in 0..MPW {
                let idx = y * MPW + x;
                let n = deep_count(x, y);
                for s in 0..n {
                    heap[ri..ri + 2].copy_from_slice(&half_bits(d_r_val(idx, s)).to_ne_bytes()); ri += 2;
                    heap[gi..gi + 2].copy_from_slice(&half_bits(d_g_val(idx, s)).to_ne_bytes()); gi += 2;
                    heap[bi..bi + 2].copy_from_slice(&half_bits(d_b_val(idx, s)).to_ne_bytes()); bi += 2;
                    heap[zi..zi + 4].copy_from_slice(&d_z_val(idx, s).to_ne_bytes()); zi += 4;
                }
            }
        }
        heap
    }

    fn deep_frame_buffer() -> DeepFrameBuffer {
        let (r0, g0, b0, z0, _total) = deep_sub_offsets();
        let hs = pixel_type_size(PixelType::Half).unwrap();
        let fs = pixel_type_size(PixelType::Float).unwrap();
        let mut fb = DeepFrameBuffer::new();
        fb.insert_sample_count_slice(Slice {
            type_: PixelType::Uint,
            base_offset: 0,
            x_stride: 4,
            y_stride: 4 * MPW as usize,
            x_sampling: 1,
            y_sampling: 1,
            fill_value: 0.0,
            x_tile_coords: false,
            y_tile_coords: false,
        })
        .unwrap();
        // x_stride/y_stride are unused for addressing in the flat-heap model;
        // base_offset selects the channel's sub-heap; sample_stride = elem size.
        fb.insert("R", DeepSlice::new(PixelType::Half, r0, 0, 0, hs, 1, 1, 0.0, false, false).unwrap()).unwrap();
        fb.insert("G", DeepSlice::new(PixelType::Half, g0, 0, 0, hs, 1, 1, 0.0, false, false).unwrap()).unwrap();
        fb.insert("B", DeepSlice::new(PixelType::Half, b0, 0, 0, hs, 1, 1, 0.0, false, false).unwrap()).unwrap();
        fb.insert("Z", DeepSlice::new(PixelType::Float, z0, 0, 0, fs, 1, 1, 0.0, false, false).unwrap()).unwrap();
        fb
    }

    // --- KNOWN headers (must match oracle.cpp) ----------------------------
    fn flat_header(name: &str, comp: Compression, tiled: bool) -> Header {
        let mut h = Header::with_dimensions(
            MPW, MPH, 1.0, V2f { x: 0.0, y: 0.0 }, 1.0, LineOrder::IncreasingY, comp,
        )
        .unwrap();
        h.set_name(name).unwrap();
        h.set_type(if tiled { TILED_IMAGE } else { SCANLINE_IMAGE }).unwrap();
        let mut cl = ChannelList::new();
        cl.insert("R", Channel::new(PixelType::Half, 1, 1, false)).unwrap();
        cl.insert("G", Channel::new(PixelType::Half, 1, 1, false)).unwrap();
        cl.insert("B", Channel::new(PixelType::Half, 1, 1, false)).unwrap();
        cl.insert("Z", Channel::new(PixelType::Float, 1, 1, false)).unwrap();
        h.insert("channels", ChannelListAttribute::new(cl)).unwrap();
        h.insert("owner", StringAttribute::new(ExrString::from("exr-rs"))).unwrap();
        h.insert("parityTag", IntAttribute::new(31337)).unwrap();
        if tiled {
            h.insert(
                "tiles",
                TileDescriptionAttribute::new(TileDescription {
                    x_size: MP_TILE,
                    y_size: MP_TILE,
                    mode: LevelMode::OneLevel,
                    rounding_mode: LevelRoundingMode::RoundDown,
                }),
            )
            .unwrap();
        }
        h
    }

    fn deep_header(name: &str, comp: Compression) -> Header {
        let mut h = Header::with_dimensions(
            MPW, MPH, 1.0, V2f { x: 0.0, y: 0.0 }, 1.0, LineOrder::IncreasingY, comp,
        )
        .unwrap();
        h.set_name(name).unwrap();
        h.set_type(DEEP_SCANLINE).unwrap();
        let mut cl = ChannelList::new();
        cl.insert("R", Channel::new(PixelType::Half, 1, 1, false)).unwrap();
        cl.insert("G", Channel::new(PixelType::Half, 1, 1, false)).unwrap();
        cl.insert("B", Channel::new(PixelType::Half, 1, 1, false)).unwrap();
        cl.insert("Z", Channel::new(PixelType::Float, 1, 1, false)).unwrap();
        h.insert("channels", ChannelListAttribute::new(cl)).unwrap();
        h.insert("owner", StringAttribute::new(ExrString::from("exr-rs"))).unwrap();
        h.insert("parityTag", IntAttribute::new(31337)).unwrap();
        h
    }

    fn known_headers() -> [Header; 3] {
        [
            flat_header("rgba", Compression::NoCompression, false),
            flat_header("tiled", Compression::Zip, true),
            deep_header("deep", Compression::Zips),
        ]
    }

    /// Write the KNOWN 3-part file with OUR writer + the typed Part wrappers.
    fn write_known_multipart() -> Vec<u8> {
        let scan_px = flat_pixels(0);
        let tile_px = flat_pixels(1000);
        let sc = deep_count_buffer();
        let heap = deep_heap();

        let mut out = MemOStream::new();
        {
            let headers = known_headers();
            let mut mp = MultiPartOutputFile::new(&mut out, &headers).unwrap();
            assert_eq!(mp.parts(), 3);
            {
                let mut p = mp.output_part_wrapper(0).unwrap();
                p.set_frame_buffer(&flat_frame_buffer()).unwrap();
                p.write_pixels(&scan_px, MPH).unwrap();
            }
            {
                let mut p = mp.tiled_output_part_wrapper(1).unwrap();
                p.set_frame_buffer(&flat_frame_buffer()).unwrap();
                let nx = p.num_x_tiles(0).unwrap();
                let ny = p.num_y_tiles(0).unwrap();
                p.write_tiles(&tile_px, 0, nx - 1, 0, ny - 1, 0, 0).unwrap();
            }
            {
                let mut p = mp.deep_scanline_output_part_wrapper(2).unwrap();
                p.set_frame_buffer(&deep_frame_buffer()).unwrap();
                p.write_pixels(&sc, &heap, MPH).unwrap();
            }
        }
        out.into_data()
    }

    fn golden_multipart_path() -> PathBuf {
        Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests")
            .join("parity")
            .join("golden_multipart.exr")
    }

    /// Read all 3 parts via our *InputPart wrappers + assert every part's
    /// metadata + pixels/counts/samples bit-exact vs the KNOWN image.
    fn assert_multipart_is_known(bytes: Vec<u8>) {
        let mut inp = MemIStream::new(bytes);
        let mut mp = MultiPartInputFile::new(&mut inp).unwrap();
        assert_eq!(mp.parts(), 3, "numParts");
        assert_eq!(mp.part_type(0).unwrap(), SCANLINE_IMAGE);
        assert_eq!(mp.part_type(1).unwrap(), TILED_IMAGE);
        assert_eq!(mp.part_type(2).unwrap(), DEEP_SCANLINE);
        assert_eq!(mp.header(0).unwrap().name().unwrap(), "rgba");
        assert_eq!(mp.header(1).unwrap().name().unwrap(), "tiled");
        assert_eq!(mp.header(2).unwrap().name().unwrap(), "deep");
        for p in 0..3 {
            let h = mp.header(p).unwrap();
            assert_eq!(
                h.typed_attribute::<ExrString>("owner").unwrap().value.as_str().unwrap(),
                "exr-rs",
                "part {p} owner"
            );
            assert_eq!(h.typed_attribute::<i32>("parityTag").unwrap().value, 31337, "part {p} parityTag");
        }

        // Part 0: scanline.
        {
            let mut p = mp.input_part_wrapper(0).unwrap();
            p.set_frame_buffer(&flat_frame_buffer()).unwrap();
            let mut got = vec![0u8; FLAT_PIXEL_BYTES * (MPW * MPH) as usize];
            p.read_pixels(0, MPH - 1, &mut got).unwrap();
            assert_flat_buffer_is_known(&got, 0, "part0 scanline");
        }
        // Part 1: tiled.
        {
            let mut p = mp.tiled_input_part_wrapper(1).unwrap();
            p.set_frame_buffer(&flat_frame_buffer()).unwrap();
            let nx = p.num_x_tiles(0).unwrap();
            let ny = p.num_y_tiles(0).unwrap();
            let mut got = vec![0u8; FLAT_PIXEL_BYTES * (MPW * MPH) as usize];
            p.read_tiles(0, nx - 1, 0, ny - 1, 0, 0, &mut got).unwrap();
            assert_flat_buffer_is_known(&got, 1000, "part1 tiled");
        }
        // Part 2: deep scanline (two-pass).
        {
            let mut p = mp.deep_scanline_input_part_wrapper(2).unwrap();
            p.set_frame_buffer(&deep_frame_buffer()).unwrap();
            let sc_expected = deep_count_buffer();
            let mut counts = vec![0u8; sc_expected.len()];
            p.read_pixel_sample_counts(0, MPH - 1, &mut counts).unwrap();
            assert_eq!(counts, sc_expected, "part2 deep counts bit-exact");
            let heap_expected = deep_heap();
            let mut heap = vec![0u8; heap_expected.len()];
            p.read_pixels(0, MPH - 1, &counts, &mut heap).unwrap();
            assert_eq!(heap, heap_expected, "part2 deep samples bit-exact");
        }
    }

    // ======================================================================
    // ours -> ours : in-memory multipart round trip (always runs; no C++).
    // ======================================================================
    #[test]
    fn ours_write_then_ours_read_multipart_round_trip() {
        let bytes = write_known_multipart();
        assert_multipart_is_known(bytes);
    }

    // ======================================================================
    // (a) C++ -> ours : read the committed golden_multipart.exr with ours.
    // ======================================================================
    #[test]
    fn cpp_golden_multipart_read_by_ours_bit_exact() {
        let Some(golden) = super::support::fixture_or_skip(
            "cpp_golden_multipart_read_by_ours_bit_exact",
            golden_multipart_path(),
            "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
        ) else {
            return;
        };
        let bytes = std::fs::read(&golden).expect("read golden_multipart.exr");
        assert_multipart_is_known(bytes);
        eprintln!("OK (a) C++ golden_multipart.exr read by ours: 3 parts, all pixels/counts/samples bit-exact.");
    }

    // --- Parser for the oracle's `read-multipart` machine-readable output --
    #[derive(Default)]
    struct PartView {
        name: String,
        type_: String,
        owner: Option<String>,
        parity: Option<i32>,
        fpix: Vec<(String, i32, i32, u64, bool)>, // chan,x,y,bits,is_half
        dcnt: Vec<(i32, i32, u32)>,                // x,y,n
        dsmp: Vec<(String, i32, i32, u32, u64, bool)>, // chan,x,y,s,bits,is_half
    }

    fn parse_read_multipart(stdout: &str) -> Vec<PartView> {
        let mut parts: Vec<PartView> = Vec::new();
        let ensure = |parts: &mut Vec<PartView>, p: usize| {
            while parts.len() <= p { parts.push(PartView::default()); }
        };
        for line in stdout.lines() {
            let mut it = line.split_whitespace();
            match it.next() {
                Some("PART") => {
                    let p: usize = it.next().unwrap().parse().unwrap();
                    let name = it.next().unwrap().to_string();
                    let ty = it.next().unwrap().to_string();
                    ensure(&mut parts, p);
                    parts[p].name = name;
                    parts[p].type_ = ty;
                }
                Some("PATTR") => {
                    let p: usize = it.next().unwrap().parse().unwrap();
                    let name = it.next().unwrap();
                    let _ty = it.next().unwrap();
                    let val = it.collect::<Vec<_>>().join(" ");
                    ensure(&mut parts, p);
                    if name == "owner" { parts[p].owner = Some(val); }
                    else if name == "parityTag" { parts[p].parity = Some(val.parse().unwrap()); }
                }
                Some("FPIX") => {
                    let p: usize = it.next().unwrap().parse().unwrap();
                    let chan = it.next().unwrap().to_string();
                    let x: i32 = it.next().unwrap().parse().unwrap();
                    let y: i32 = it.next().unwrap().parse().unwrap();
                    let hex = it.next().unwrap();
                    let is_half = hex.len() == 4;
                    let bits = u64::from_str_radix(hex, 16).unwrap();
                    ensure(&mut parts, p);
                    parts[p].fpix.push((chan, x, y, bits, is_half));
                }
                Some("DCNT") => {
                    let p: usize = it.next().unwrap().parse().unwrap();
                    let x: i32 = it.next().unwrap().parse().unwrap();
                    let y: i32 = it.next().unwrap().parse().unwrap();
                    let n: u32 = it.next().unwrap().parse().unwrap();
                    ensure(&mut parts, p);
                    parts[p].dcnt.push((x, y, n));
                }
                Some("DSMP") => {
                    let p: usize = it.next().unwrap().parse().unwrap();
                    let chan = it.next().unwrap().to_string();
                    let x: i32 = it.next().unwrap().parse().unwrap();
                    let y: i32 = it.next().unwrap().parse().unwrap();
                    let s: u32 = it.next().unwrap().parse().unwrap();
                    let hex = it.next().unwrap();
                    let is_half = hex.len() == 4;
                    let bits = u64::from_str_radix(hex, 16).unwrap();
                    ensure(&mut parts, p);
                    parts[p].dsmp.push((chan, x, y, s, bits, is_half));
                }
                _ => {}
            }
        }
        parts
    }

    // ======================================================================
    // (b) ours -> C++ : our writer's multipart file, read back by the oracle.
    // ======================================================================
    #[test]
    fn ours_write_multipart_read_by_cpp_oracle_bit_exact() {
        let Some(oracle) = super::support::oracle_or_skip("ours_write_multipart_read_by_cpp_oracle_bit_exact") else {
            return;
        };

        // 1) Write the KNOWN multipart file with OUR writer to a temp file.
        let out_path = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join("parity_multipart_ours.exr");
        let bytes = write_known_multipart();
        std::fs::write(&out_path, &bytes).unwrap();

        // 2) Have the C++ oracle READ our multipart file.
        let output = Command::new(&oracle)
            .arg("read-multipart")
            .arg(&out_path)
            .output()
            .expect("failed to run oracle read-multipart");
        let stdout = String::from_utf8_lossy(&output.stdout);
        let stderr = String::from_utf8_lossy(&output.stderr);
        assert!(
            output.status.success(),
            "oracle read-multipart failed (status {}):\nstderr:\n{stderr}",
            output.status
        );

        // 3) Compare C++'s view of every part to the KNOWN image.
        let parts = parse_read_multipart(&stdout);
        assert_eq!(parts.len(), 3, "C++ saw wrong numParts");
        let expect_names = ["rgba", "tiled", "deep"];
        let expect_types = [SCANLINE_IMAGE, TILED_IMAGE, DEEP_SCANLINE];
        for p in 0..3 {
            assert_eq!(parts[p].name, expect_names[p], "part {p} name");
            assert_eq!(parts[p].type_, expect_types[p], "part {p} type");
            assert_eq!(parts[p].owner.as_deref(), Some("exr-rs"), "part {p} owner");
            assert_eq!(parts[p].parity, Some(31337), "part {p} parityTag");
        }

        // Flat parts: every pixel bit-exact (pbias 0 for part0, 1000 for part1).
        for (p, pbias) in [(0usize, 0i32), (1usize, 1000i32)] {
            assert_eq!(
                parts[p].fpix.len(),
                (MPW * MPH * 4) as usize,
                "part {p} flat pixel count"
            );
            for (chan, x, y, bits, is_half) in &parts[p].fpix {
                let idx = y * MPW + x;
                let (expected, half) = match chan.as_str() {
                    "R" => (half_bits(r_val(idx, pbias)) as u64, true),
                    "G" => (half_bits(g_val(idx, pbias)) as u64, true),
                    "B" => (half_bits(b_val(idx, pbias)) as u64, true),
                    "Z" => (float_bits(z_val(idx, pbias)) as u64, false),
                    o => panic!("part {p} unknown channel {o}"),
                };
                assert_eq!(*is_half, half, "part {p} {chan} width");
                assert_eq!(*bits, expected, "part {p} {chan} bits at ({x},{y})");
            }
        }

        // Deep part (index 2): counts + every sample bit-exact.
        assert_eq!(parts[2].dcnt.len(), (MPW * MPH) as usize, "deep count records");
        for (x, y, n) in &parts[2].dcnt {
            assert_eq!(*n, deep_count(*x, *y) as u32, "deep count at ({x},{y})");
        }
        let mut deep_samples = 0usize;
        for (chan, x, y, s, bits, is_half) in &parts[2].dsmp {
            let idx = y * MPW + x;
            let si = *s as i32;
            let (expected, half) = match chan.as_str() {
                "R" => (half_bits(d_r_val(idx, si)) as u64, true),
                "G" => (half_bits(d_g_val(idx, si)) as u64, true),
                "B" => (half_bits(d_b_val(idx, si)) as u64, true),
                "Z" => (float_bits(d_z_val(idx, si)) as u64, false),
                o => panic!("deep unknown channel {o}"),
            };
            assert_eq!(*is_half, half, "deep {chan} width");
            assert_eq!(*bits, expected, "deep {chan} bits at ({x},{y}) sample {s}");
            deep_samples += 1;
        }
        // 4 channels * total_samples sample records expected.
        assert_eq!(deep_samples, (total_samples() * 4) as usize, "deep sample record count");

        eprintln!(
            "OK (b) ours -> C++ oracle (multipart): 3 parts (scanline/NONE, tiled/ZIP, deep/ZIPS), \
             metadata + all pixels/counts/samples read back bit-exact."
        );
    }
}

// ===========================================================================
// The golden files must actually exercise their codec
// ===========================================================================

/// Walk every committed `golden*.exr` and assert that a compressed one really
/// is compressed — chunk by chunk.
///
/// This is the guard for the defect this whole round of work started from: the
/// 7x5 KNOWN image was so small that C++ stored PIZ, DWAA, DWAB and both HTJ2K
/// chunks RAW, so five codecs' "byte-identical to C++" and "decode matches C++"
/// tests passed while never running the codec at all. Scanning the directory rather than listing
/// file names means a new golden is covered the moment `xtask` writes it — the
/// check cannot be forgotten for the next codec.
#[test]
fn every_compressed_golden_actually_compresses() {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests").join("parity");
    let mut entries: Vec<PathBuf> = std::fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("read_dir {}: {e}", dir.display()))
        .filter_map(|e| e.ok().map(|e| e.path()))
        .filter(|p| {
            p.extension().and_then(|e| e.to_str()) == Some("exr")
                && p.file_name().and_then(|n| n.to_str()).is_some_and(|n| n.starts_with("golden"))
        })
        .collect();
    entries.sort();
    assert!(!entries.is_empty(), "no goldens in {}", dir.display());

    let mut checked = Vec::new();
    let mut skipped = Vec::new();
    for path in &entries {
        let name = path.file_name().unwrap_or_default().to_string_lossy().into_owned();
        // Deep and multipart goldens are lossless-only container tests; the
        // raw-size model below is for single-part flat files.
        if name.contains("deep") || name.contains("multipart") {
            skipped.push(format!("{name} (deep/multipart)"));
            continue;
        }
        // Sub-sampling matrix goldens (`golden_sub_*`): 64x64 is sized for chunk-boundary
        // coverage across every codec's scan-line count (1/16/32/256), not
        // for this test's "enough raw bytes to prove a codec ran" heuristic
        // -- an RLE/ZIPS chunk here is a single 64-pixel scanline (well under
        // `SHRINK_FLOOR`). Their compression correctness is proven byte/
        // pixel-exact by `sub_matrix_cpp_golden_matches_ours` and
        // `sub_matrix_ours_written_read_by_cpp_oracle` instead, a strictly
        // stronger guarantee than "the codec shrank the data".
        if name.starts_with("golden_sub_") {
            skipped.push(format!("{name} (sub-sampling matrix, checked elsewhere)"));
            continue;
        }
        let mut is = StdIfStream::open(path.to_str().unwrap()).expect("open golden");
        let inf = InputFile::new(&mut is);
        let Ok(inf) = inf else {
            skipped.push(format!("{name} (not a flat scanline/tiled file)"));
            continue;
        };
        let h = inf.header();
        if h.compression().unwrap() == Compression::NoCompression {
            skipped.push(format!("{name} (uncompressed by design)"));
            continue;
        }
        if h.channels().unwrap().iter().any(|(_, c)| c.x_sampling != 1 || c.y_sampling != 1) {
            // The luminance-chroma golden: its raw-size math needs per-channel
            // sampling, and it is covered end-to-end by `tests/rgba_yc.rs`.
            skipped.push(format!("{name} (subsampled)"));
            continue;
        }
        drop(inf);
        support::assert_chunks_compressed(path);
        checked.push(name);
    }
    eprintln!(
        "chunk-compression gate: {} golden(s) verified compressed, {} skipped\n  checked: {}\n  skipped: {}",
        checked.len(),
        skipped.len(),
        checked.join(", "),
        skipped.join(", ")
    );
    assert!(
        checked.len() >= 20,
        "only {} goldens were verified compressed -- the gate has lost coverage",
        checked.len()
    );
}


// ===========================================================================
// Incomplete / truncated files
// ===========================================================================

/// Truncating a real C++-written file at many points must never panic.
///
/// "Incomplete files / offset reconstruction" used to have no honest test: the only corrupt fixtures lived in the corpus,
/// which itself never ran. A truncated file is the commonest real-world
/// corruption (an interrupted render), and the read path is the one that faces
/// untrusted bytes, so the invariant is asserted here against genuine C++
/// output rather than a synthetic header.
///
/// The assertion is deliberately the one that is unconditionally true: `Err` or
/// a short read are both legitimate (C++ reconstructs whatever chunks exist),
/// a **panic** never is. Pinning anything stronger here would pin behaviour the
/// offset-table reconstruction work is still settling.
#[test]
fn truncated_goldens_never_panic() {
    let name = "truncated_goldens_never_panic";
    let mut checked = 0usize;
    for file in ["golden.exr", "golden_zip.exr", "golden_piz.exr", "golden_tiled_zip_one.exr"] {
        let Some(path) = support::fixture_or_skip(
            name,
            parity_file(file),
            "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
        ) else {
            return;
        };
        let full = std::fs::read(&path).expect("read golden");
        // Cut inside the header, inside the offset table, and at three points
        // inside the chunk region.
        for num in [1u64, 3, 5, 7, 9] {
            let cut = (full.len() as u64 * num / 10) as usize;
            let bytes = full[..cut].to_vec();
            let outcome = catch_unwind(AssertUnwindSafe(|| {
                let mut is = MemIStream::new(bytes);
                let mut inf = InputFile::new(&mut is)?;
                let dw = inf.header().data_window()?;
                let w = (dw.max.x - dw.min.x + 1) as usize;
                let h = (dw.max.y - dw.min.y + 1) as usize;
                let fb = known_frame_buffer();
                let mut out = vec![0u8; PIXEL_BYTES * w * h];
                inf.set_frame_buffer(&fb)?;
                inf.read_pixels(dw.min.y, dw.max.y, &mut out)?;
                Ok::<(), exr_core::ExrError>(())
            }));
            assert!(
                outcome.is_ok(),
                "{file} truncated to {cut}/{} bytes PANICKED -- a malformed file must \
                 produce an error, never a panic",
                full.len()
            );
            checked += 1;
        }
    }
    assert_eq!(checked, 20, "expected 4 files x 5 truncation points");
}

// ===========================================================================
// Sub-sampling matrix: 12 codecs x 4 samplings. An HTJ2K y-subsampling bug slipped through because no test
// exercised channel sub-sampling for 11 of the 12 codecs; this matrix closes
// that gap for every codec, both directions, plus our own round trip.
//
// Two channels, alphabetical: "A" (HALF, always unsampled -- the reference)
// and "S" (HALF, the (xSampling, ySampling) under test, in
// {(1,1),(2,1),(1,2),(2,2)}). `oracle.cpp`'s `write-sub`/`dump-sub` (generic,
// reuses the existing `do_dump_subsampled`) mirror `write-dwa-sub`/
// `dump-dwa-sub` above but for every codec. 64x64 so every codec's chunk
// height (1/16/32/256 scan lines) either divides it evenly or covers it in
// one chunk, and xs/ys in {1,2} both divide 64 with a (0,0) origin.
//
// Tiled sub-sampling is out of scope for an oracle round trip: `Header::
// sanity_check` rejects x/y sampling != 1 for TILED headers unconditionally
// (`header.rs:1020-1037`, matching C++ `ImfHeader.cpp:1221-1227` -- ported
// 1:1, cited there), so no real C++ writer can ever produce that file to
// round-trip against; `header.rs`'s own unit tests
// (`sanity_check_rejects_tiled_x_subsampled_channel` /
// `..._y_subsampled_channel`) pin that rejection directly.
// ===========================================================================

const SUB_W: i32 = 64;
const SUB_H: i32 = 64;

/// Every codec under test, as (`oracle.cpp`/`xtask` arg name, [`Compression`]).
/// Must match `xtask/src/main.rs`'s sub-matrix loop in `exr_goldens()` exactly.
const SUB_MATRIX_CODECS: &[(&str, Compression)] = &[
    ("none", Compression::NoCompression),
    ("rle", Compression::Rle),
    ("zip", Compression::Zip),
    ("zips", Compression::Zips),
    ("piz", Compression::Piz),
    ("b44", Compression::B44),
    ("b44a", Compression::B44a),
    ("pxr24", Compression::Pxr24),
    ("dwaa", Compression::Dwaa),
    ("dwab", Compression::Dwab),
    ("htj2k256", Compression::Htj2k256),
    ("htj2k32", Compression::Htj2k32),
];

/// (xSampling, ySampling) cells under test. Must match `xtask`'s sub-matrix loop.
const SUB_MATRIX_SAMPLINGS: &[(i32, i32)] = &[(1, 1), (2, 1), (1, 2), (2, 2)];

/// Mirrors `oracle.cpp`'s `sub_a_val` exactly (full-width `SUB_W`, even for the
/// sampled channel's reduced grid -- see `oracle.cpp`'s comment on `sub_s_val`).
fn sub_a_val(x: i32, y: i32) -> f32 { 1.0 + (y * SUB_W + x) as f32 * 0.1 }
/// Mirrors `oracle.cpp`'s `sub_s_val` exactly.
fn sub_s_val(x: i32, y: i32) -> f32 { -30.0 + (y * SUB_W + x) as f32 * 0.2 }

fn sub_channels(xs: i32, ys: i32) -> ChannelList {
    let mut channels = ChannelList::new();
    channels.insert("A", Channel::new(PixelType::Half, 1, 1, false)).unwrap();
    channels.insert("S", Channel::new(PixelType::Half, xs, ys, false)).unwrap();
    channels
}

fn sub_header(compression: Compression, xs: i32, ys: i32) -> Header {
    let mut hdr = Header::with_dimensions(
        SUB_W,
        SUB_H,
        1.0,
        V2f { x: 0.0, y: 0.0 },
        1.0,
        LineOrder::IncreasingY,
        compression,
    )
    .unwrap();
    hdr.insert("channels", ChannelListAttribute::new(sub_channels(xs, ys))).unwrap();
    hdr
}

/// A dump-layout frame buffer (matches `do_dump_subsampled`/
/// `dwa_sub_dump_frame_buffer` above): channels alphabetical (A, then S), each
/// channel's own tightly packed `(w/xSampling) x (h/ySampling)` plane, no
/// interleaving. Returns the frame buffer plus the total buffer size.
fn sub_dump_frame_buffer(channels: &ChannelList) -> (FrameBuffer, usize) {
    let mut fb = FrameBuffer::new();
    let mut offset = 0i64;
    for (name, ch) in channels.iter() {
        let cw = (SUB_W / ch.x_sampling.max(1)) as usize;
        let chh = (SUB_H / ch.y_sampling.max(1)) as usize;
        let px = exr_core::misc::pixel_type_size(ch.type_).unwrap();
        fb.insert(
            name,
            Slice {
                type_: ch.type_,
                base_offset: offset,
                x_stride: px,
                y_stride: px * cw,
                x_sampling: ch.x_sampling,
                y_sampling: ch.y_sampling,
                fill_value: 0.0,
                x_tile_coords: false,
                y_tile_coords: false,
            },
        )
        .unwrap();
        offset += (px * cw * chh) as i64;
    }
    (fb, offset as usize)
}

/// The KNOWN pixel formulas in dump-layout order (alphabetical channel, then
/// row-major over ITS OWN reduced grid) -- mirrors `oracle.cpp`'s `write-sub`
/// (`sub_a_val`/`sub_s_val`) exactly.
fn sub_pixel_buffer(channels: &ChannelList) -> Vec<u8> {
    let mut out = Vec::new();
    for (name, ch) in channels.iter() {
        let cw = (SUB_W / ch.x_sampling.max(1)) as usize;
        let chh = (SUB_H / ch.y_sampling.max(1)) as usize;
        for cy in 0..chh {
            for cx in 0..cw {
                let v = match name.to_str().unwrap_or("") {
                    "A" => sub_a_val(cx as i32, cy as i32),
                    "S" => sub_s_val(cx as i32, cy as i32),
                    _ => unreachable!("sub_channels() must match this match arm set"),
                };
                out.extend_from_slice(&Half::from_f32(v).bits().to_le_bytes());
            }
        }
        let _ = ch;
    }
    out
}

fn sub_golden_name(codec: &str, xs: i32, ys: i32) -> String {
    format!("golden_sub_{codec}_x{xs}y{ys}.exr")
}

/// (own round trip) Write with OUR writer, read back with OUR reader, no
/// oracle involved. For a lossless codec the values must survive exactly; for
/// a lossy one they will not, but the LENGTH must still be exactly right --
/// this alone would have caught the HTJ2K y-subsampling bug (it produced a
/// wrongly-SIZED buffer, 2048 instead of 1536 bytes, not merely wrong values).
fn sub_matrix_ours_round_trip_cell(codec: &str, compression: Compression, xs: i32, ys: i32) -> Result<(), String> {
    let header = sub_header(compression, xs, ys);
    let channels = sub_channels(xs, ys);
    let (fb, total) = sub_dump_frame_buffer(&channels);
    let pixels = sub_pixel_buffer(&channels);
    if pixels.len() != total {
        return Err(format!("test fixture bug: pixel buffer {} != frame buffer size {total}", pixels.len()));
    }

    let out_path = PathBuf::from(env!("CARGO_TARGET_TMPDIR"))
        .join(format!("parity_exr_sub_rt_{codec}_x{xs}y{ys}.exr"));
    {
        let mut os = StdOfStreamWrap::create(out_path.to_str().unwrap());
        let mut of = OutputFile::new(&mut os.0, &header).map_err(|e| format!("OutputFile::new: {e}"))?;
        of.set_frame_buffer(&fb).map_err(|e| format!("write set_frame_buffer: {e}"))?;
        of.write_pixels(&pixels, SUB_H).map_err(|e| format!("write_pixels: {e}"))?;
    }

    let mut is = StdIfStream::open(out_path.to_str().unwrap()).map_err(|e| format!("open: {e}"))?;
    let mut inf = InputFile::new(&mut is).map_err(|e| format!("InputFile::new: {e}"))?;
    let mut ours = vec![0u8; total];
    inf.set_frame_buffer(&fb).map_err(|e| format!("read set_frame_buffer: {e}"))?;
    inf.read_pixels(0, SUB_H - 1, &mut ours).map_err(|e| format!("read_pixels: {e}"))?;

    if ours.len() != pixels.len() {
        return Err(format!("round-trip length mismatch: wrote {} read back {}", pixels.len(), ours.len()));
    }
    if !compression.is_lossy() && ours != pixels {
        let at = ours.iter().zip(&pixels).position(|(a, b)| a != b).unwrap_or(0);
        return Err(format!("lossless round trip differs at byte {at} (ours={:#04x} expected={:#04x})", ours[at], pixels[at]));
    }
    Ok(())
}

/// (a) C++ oracle golden -> our reader. Lossless: exact match to the KNOWN
/// formula. Lossy: exact match to the committed C++ decode dump.
fn sub_matrix_cpp_golden_matches_ours_cell(codec: &str, compression: Compression, xs: i32, ys: i32) -> Result<(), String> {
    let golden_file = sub_golden_name(codec, xs, ys);
    let golden = parity_file(&golden_file);
    if !golden.exists() {
        return Err(format!("missing golden {golden_file} -- run `cargo run -p xtask -- parity-exr`"));
    }

    let mut is = StdIfStream::open(golden.to_str().unwrap()).map_err(|e| format!("open golden: {e}"))?;
    let mut inf = InputFile::new(&mut is).map_err(|e| format!("InputFile::new: {e}"))?;
    if inf.header().compression().map_err(|e| e.to_string())? != compression {
        return Err("header compression mismatch".into());
    }
    let channels = sub_channels(xs, ys);
    let (fb, total) = sub_dump_frame_buffer(&channels);
    let mut ours = vec![0u8; total];
    inf.set_frame_buffer(&fb).map_err(|e| format!("set_frame_buffer: {e}"))?;
    inf.read_pixels(0, SUB_H - 1, &mut ours).map_err(|e| format!("read_pixels: {e}"))?;

    let expected: Vec<u8> = if compression.is_lossy() {
        let dump_path = PathBuf::from(format!("{}.dump", golden.display()));
        if !dump_path.exists() {
            return Err(format!("missing decode dump {} -- run `cargo run -p xtask -- parity-exr`", dump_path.display()));
        }
        std::fs::read(&dump_path).map_err(|e| format!("read dump: {e}"))?
    } else {
        sub_pixel_buffer(&channels)
    };

    if ours.len() != expected.len() {
        return Err(format!("decode length mismatch: ours {} expected {}", ours.len(), expected.len()));
    }
    if ours != expected {
        let at = ours.iter().zip(&expected).position(|(a, b)| a != b).unwrap_or(0);
        return Err(format!("decode differs at byte {at} (ours={:#04x} expected={:#04x})", ours[at], expected[at]));
    }
    Ok(())
}

/// (b) our writer -> C++ oracle `dump-sub`. Lossless: the oracle's decode of
/// OUR file must match the KNOWN formula exactly (a real C++ reader
/// reconstructs a lossless stream exactly, so no separate golden decode is
/// needed). Lossy: the oracle's decode of OUR file must match the oracle's OWN
/// decode of the committed golden (both are C++ decodes of the identical
/// formulas -- proves our WRITER emits a stream a genuine C++ reader decodes
/// the same way, not merely that our own reader agrees with our own writer).
fn sub_matrix_ours_written_read_by_cpp_oracle_cell(
    oracle: &Path,
    codec: &str,
    compression: Compression,
    xs: i32,
    ys: i32,
) -> Result<(), String> {
    let channels = sub_channels(xs, ys);
    let (fb, _total) = sub_dump_frame_buffer(&channels);
    let pixels = sub_pixel_buffer(&channels);

    let out_path = PathBuf::from(env!("CARGO_TARGET_TMPDIR"))
        .join(format!("parity_exr_sub_ours_{codec}_x{xs}y{ys}.exr"));
    {
        let header = sub_header(compression, xs, ys);
        let mut os = StdOfStreamWrap::create(out_path.to_str().unwrap());
        let mut of = OutputFile::new(&mut os.0, &header).map_err(|e| format!("OutputFile::new: {e}"))?;
        of.set_frame_buffer(&fb).map_err(|e| format!("set_frame_buffer: {e}"))?;
        of.write_pixels(&pixels, SUB_H).map_err(|e| format!("write_pixels: {e}"))?;
    }

    let ours_dump_path = PathBuf::from(env!("CARGO_TARGET_TMPDIR"))
        .join(format!("parity_exr_sub_ours_{codec}_x{xs}y{ys}.exr.dump"));
    let output = Command::new(oracle)
        .arg("dump-sub")
        .arg(&out_path)
        .arg(&ours_dump_path)
        .output()
        .map_err(|e| format!("failed to run oracle dump-sub: {e}"))?;
    if !output.status.success() {
        return Err(format!("oracle dump-sub failed: {}", String::from_utf8_lossy(&output.stderr)));
    }
    let ours_dump = std::fs::read(&ours_dump_path).map_err(|e| format!("read {}: {e}", ours_dump_path.display()))?;

    let expected: Vec<u8> = if compression.is_lossy() {
        let golden_file = sub_golden_name(codec, xs, ys);
        let golden_dump_path = PathBuf::from(format!("{}.dump", parity_file(&golden_file).display()));
        if !golden_dump_path.exists() {
            return Err(format!("missing golden decode dump {} -- run `cargo run -p xtask -- parity-exr`", golden_dump_path.display()));
        }
        std::fs::read(&golden_dump_path).map_err(|e| format!("read {}: {e}", golden_dump_path.display()))?
    } else {
        sub_pixel_buffer(&channels)
    };

    if ours_dump.len() != expected.len() {
        return Err(format!("C++ decode of our file: length mismatch {} vs expected {}", ours_dump.len(), expected.len()));
    }
    if ours_dump != expected {
        let at = ours_dump.iter().zip(&expected).position(|(a, b)| a != b).unwrap_or(0);
        return Err(format!(
            "C++ decode of our file differs from expected at byte {at} (ours={:#04x} expected={:#04x})",
            ours_dump[at], expected[at]
        ));
    }
    Ok(())
}

/// Run `f` over every (codec, sampling) cell, print a result table, and panic
/// listing every failing cell (not just the first) so a red matrix is fully
/// diagnosable from one `cargo test` run.
fn run_sub_matrix(test_name: &str, mut f: impl FnMut(&str, Compression, i32, i32) -> Result<(), String>) {
    let mut failures = Vec::new();
    let mut rows = Vec::new();
    for &(codec, compression) in SUB_MATRIX_CODECS {
        for &(xs, ys) in SUB_MATRIX_SAMPLINGS {
            let result = f(codec, compression, xs, ys);
            let cell = format!("{codec:<8} x{xs}y{ys}");
            match &result {
                Ok(()) => rows.push(format!("{cell}: OK")),
                Err(e) => {
                    rows.push(format!("{cell}: FAIL -- {e}"));
                    failures.push(format!("{cell}: {e}"));
                }
            }
        }
    }
    eprintln!("--- {test_name} matrix ({} cells) ---", rows.len());
    for row in &rows {
        eprintln!("{row}");
    }
    assert!(
        failures.is_empty(),
        "{test_name}: {} of {} cells FAILED:\n{}",
        failures.len(),
        rows.len(),
        failures.join("\n")
    );
}

#[test]
fn sub_matrix_ours_round_trip() {
    run_sub_matrix("sub_matrix_ours_round_trip", |codec, compression, xs, ys| {
        sub_matrix_ours_round_trip_cell(codec, compression, xs, ys)
    });
}

#[test]
fn sub_matrix_cpp_golden_matches_ours() {
    // Canary: the whole matrix is regenerated together by `xtask`, so if the
    // first golden is missing, treat it the same way every other fixture-gated
    // test here does (FAIL unless `EXR_ALLOW_SKIP=1`).
    if support::fixture_or_skip(
        "sub_matrix_cpp_golden_matches_ours",
        parity_file(&sub_golden_name("none", 1, 1)),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the sub-sampling matrix goldens.",
    )
    .is_none()
    {
        return;
    }
    run_sub_matrix("sub_matrix_cpp_golden_matches_ours", |codec, compression, xs, ys| {
        sub_matrix_cpp_golden_matches_ours_cell(codec, compression, xs, ys)
    });
}

#[test]
fn sub_matrix_ours_written_read_by_cpp_oracle() {
    let Some(oracle) = support::oracle_or_skip("sub_matrix_ours_written_read_by_cpp_oracle") else {
        return;
    };
    run_sub_matrix("sub_matrix_ours_written_read_by_cpp_oracle", |codec, compression, xs, ys| {
        sub_matrix_ours_written_read_by_cpp_oracle_cell(&oracle, codec, compression, xs, ys)
    });
}

// ===========================================================================
// Byte-exact `Name` — a channel name with an invalid-UTF-8 byte, an
// attribute name starting with an invalid-UTF-8 lead byte, and an attribute
// name at exactly `Name::MAX_LENGTH` (255 bytes, which also forces
// `LONG_NAMES_FLAG`). `oracle.cpp`'s `write-nonutf8-names` /
// `dump-nonutf8-attr` (additive; the channel/pixel half of direction (b)
// reuses the existing generic `dump` mode, unmodified).
//
//   (a) C++ writes `golden_nonutf8_names.exr` -> our `InputFile` reads the
//       channel list, the two odd-named `int` attributes, and every pixel,
//       byte-exact against the values `oracle.cpp` chose.
//   (b) we write an equivalent file with our `OutputFile` -> the C++ oracle's
//       (unmodified) `dump` mode decodes our pixels, and the new
//       `dump-nonutf8-attr` mode decodes our two odd-named attributes via a
//       real `Header::findTypedAttribute` -- a genuine live C++ read of our
//       file, not a self-consistency check.
// ===========================================================================

const NN_W: i32 = 4;
const NN_H: i32 = 3;

fn nn_r_val(idx: i32) -> Half {
    Half::from_f32(1.0 + idx as f32 * 0.5)
}
fn nn_z_val(idx: i32) -> f32 {
    100.0 + idx as f32 * 2.0
}

/// "Z\xE9" -- 'Z' followed by an invalid-UTF-8 continuation byte on its own.
/// Must match `oracle.cpp`'s `nn_channel_name()` byte-for-byte.
fn nn_channel_name() -> Name {
    Name::new([b'Z', 0xE9].as_slice())
}
/// "\xFFattr" -- 0xFF is never valid UTF-8 in any position. Must match
/// `oracle.cpp`'s `nn_attr_name_nonutf8()` byte-for-byte.
fn nn_attr_name_nonutf8() -> Name {
    let mut bytes = vec![0xFFu8];
    bytes.extend_from_slice(b"attr");
    Name::new(bytes.as_slice())
}
/// 255 'x' bytes -- exactly `Name::MAX_LENGTH`. Must match `oracle.cpp`'s
/// `nn_attr_name_maxlen()`.
fn nn_attr_name_maxlen() -> Name {
    Name::new(vec![b'x'; 255].as_slice())
}

const NN_ATTR_NONUTF8_VALUE: i32 = 12345;
const NN_ATTR_MAXLEN_VALUE: i32 = 255001;

fn nn_channels() -> ChannelList {
    let mut cl = ChannelList::new();
    cl.insert("R", Channel::new(PixelType::Half, 1, 1, false)).unwrap();
    cl.insert(nn_channel_name(), Channel::new(PixelType::Float, 1, 1, false))
        .unwrap();
    cl
}

fn nn_header() -> Header {
    let mut hdr = Header::with_dimensions(
        NN_W,
        NN_H,
        1.0,
        V2f { x: 0.0, y: 0.0 },
        1.0,
        LineOrder::IncreasingY,
        Compression::NoCompression,
    )
    .unwrap();
    hdr.insert("channels", ChannelListAttribute::new(nn_channels())).unwrap();
    hdr.insert("owner", StringAttribute::new(ExrString::from("exr-rs"))).unwrap();
    hdr.insert(nn_attr_name_nonutf8(), IntAttribute::new(NN_ATTR_NONUTF8_VALUE))
        .unwrap();
    hdr.insert(nn_attr_name_maxlen(), IntAttribute::new(NN_ATTR_MAXLEN_VALUE))
        .unwrap();
    hdr
}

/// A planar dump-layout frame buffer: `R`'s plane then `"Z\xE9"`'s plane, in
/// `ChannelList` (alphabetical, byte-wise) order -- 'R' = 0x52 sorts before
/// 'Z' = 0x5A regardless of the trailing 0xE9 byte.
fn nn_dump_frame_buffer() -> (FrameBuffer, usize) {
    let mut fb = FrameBuffer::new();
    let n = (NN_W * NN_H) as usize;
    fb.insert(
        "R",
        Slice {
            type_: PixelType::Half,
            base_offset: 0,
            x_stride: 2,
            y_stride: 2 * NN_W as usize,
            x_sampling: 1,
            y_sampling: 1,
            fill_value: 0.0,
            x_tile_coords: false,
            y_tile_coords: false,
        },
    )
    .unwrap();
    fb.insert(
        nn_channel_name(),
        Slice {
            type_: PixelType::Float,
            base_offset: (n * 2) as i64,
            x_stride: 4,
            y_stride: 4 * NN_W as usize,
            x_sampling: 1,
            y_sampling: 1,
            fill_value: 0.0,
            x_tile_coords: false,
            y_tile_coords: false,
        },
    )
    .unwrap();
    (fb, n * 2 + n * 4)
}

/// The expected pixel bytes in the same R-plane-then-Z-plane layout
/// [`nn_dump_frame_buffer`] describes, and what `oracle.cpp`'s `dump` mode
/// emits for these channels (channel-list order).
fn nn_pixel_buffer() -> Vec<u8> {
    let mut out = Vec::new();
    for idx in 0..(NN_W * NN_H) {
        out.extend_from_slice(&nn_r_val(idx).bits().to_le_bytes());
    }
    for idx in 0..(NN_W * NN_H) {
        out.extend_from_slice(&nn_z_val(idx).to_le_bytes());
    }
    out
}

fn nn_golden_path() -> PathBuf {
    parity_file("golden_nonutf8_names.exr")
}

/// (a) C++-written `golden_nonutf8_names.exr` -> our `InputFile`, byte-exact.
#[test]
fn cpp_nonutf8_names_golden_matches_ours() {
    let Some(golden) = support::fixture_or_skip(
        "cpp_nonutf8_names_golden_matches_ours",
        nn_golden_path(),
        "Run `cargo run -p xtask -- parity-exr` to regenerate the C++ goldens.",
    ) else {
        return;
    };

    let mut is = StdIfStream::open(golden.to_str().unwrap()).expect("open golden_nonutf8_names.exr");
    let mut inf = InputFile::new(&mut is).expect("InputFile::new on golden_nonutf8_names.exr");

    // Channels: the plain "R" and the non-UTF-8 "Z\xE9", byte-exact name and type.
    let cl = inf.header().channels().expect("channels").clone();
    assert!(cl.find_channel("R").is_some(), "missing channel R");
    let zname = nn_channel_name();
    let z = cl
        .find_channel(zname.as_bytes())
        .expect("missing non-UTF-8 channel \"Z\\xE9\"");
    assert_eq!(z.type_, PixelType::Float);
    assert_eq!(cl.len(), 2, "must be exactly R + \"Z\\xE9\", no more no less");

    // Attributes: "owner" (plain), the non-UTF-8-named int, and the
    // 255-byte-named int. The non-UTF-8 one cannot go through the `&str`
    // typed-attribute API, so look it up directly via `iter()` + downcast --
    // exactly what a consumer without a known-UTF-8 key must do.
    let h = inf.header();
    assert!(h.get("owner").is_ok(), "missing owner attribute");
    let a1_name = nn_attr_name_nonutf8();
    let (_, a1) = h
        .iter()
        .find(|(k, _)| k.as_bytes() == a1_name.as_bytes())
        .expect("missing non-UTF-8-named attribute \"\\xFFattr\"");
    let a1: &IntAttribute = a1
        .as_any()
        .downcast_ref()
        .expect("\"\\xFFattr\" must be an IntAttribute");
    assert_eq!(a1.value, NN_ATTR_NONUTF8_VALUE);

    let maxlen_name = "x".repeat(255);
    let a2 = h
        .typed_attribute::<i32>(&maxlen_name)
        .expect("missing 255-byte-named attribute");
    assert_eq!(a2.value, NN_ATTR_MAXLEN_VALUE);

    // Pixels: both channels, byte-exact.
    let (fb, total) = nn_dump_frame_buffer();
    let mut out = vec![0u8; total];
    inf.set_frame_buffer(&fb).expect("set_frame_buffer");
    inf.read_pixels(0, NN_H - 1, &mut out).expect("read_pixels");
    assert_eq!(out, nn_pixel_buffer());

    eprintln!(
        "OK (a) C++ golden_nonutf8_names.exr read by ours: non-UTF-8 channel + \
         attribute names, and a 255-byte attribute name, all byte-exact."
    );
}

/// (b) our `OutputFile` writes an equivalent file -> the real C++ oracle
/// reads it back (channels/pixels via the existing generic `dump` mode,
/// the two odd-named attributes via the new `dump-nonutf8-attr` mode).
#[test]
fn ours_nonutf8_names_read_by_cpp_oracle() {
    let Some(oracle) = support::oracle_or_skip("ours_nonutf8_names_read_by_cpp_oracle") else {
        return;
    };

    let out_path = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join("parity_exr_ours_nonutf8_names.exr");
    {
        let header = nn_header();
        let (fb, _total) = nn_dump_frame_buffer();
        let pixels = nn_pixel_buffer();
        let mut os = StdOfStreamWrap::create(out_path.to_str().unwrap());
        let mut of = OutputFile::new(&mut os.0, &header).expect("OutputFile::new");
        of.set_frame_buffer(&fb).expect("set_frame_buffer");
        of.write_pixels(&pixels, NN_H).expect("write_pixels");
    }

    // Channels + pixels: the existing generic `dump` mode, unmodified.
    let dump_path = PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join("parity_exr_ours_nonutf8_names.exr.dump");
    let output = Command::new(&oracle)
        .arg("dump")
        .arg(&out_path)
        .arg(&dump_path)
        .output()
        .expect("failed to run oracle dump");
    assert!(
        output.status.success(),
        "oracle dump failed (status {}):\nstderr:\n{}",
        output.status,
        String::from_utf8_lossy(&output.stderr)
    );
    let dumped = std::fs::read(&dump_path).expect("read oracle dump");
    assert_eq!(
        dumped,
        nn_pixel_buffer(),
        "C++ oracle's decode of our non-UTF-8-named channels must match the known pixel pattern"
    );

    // The two odd-named `int` attributes: the new `dump-nonutf8-attr` mode.
    let attr_dump_path =
        PathBuf::from(env!("CARGO_TARGET_TMPDIR")).join("parity_exr_ours_nonutf8_names.exr.attrs");
    let output = Command::new(&oracle)
        .arg("dump-nonutf8-attr")
        .arg(&out_path)
        .arg(&attr_dump_path)
        .output()
        .expect("failed to run oracle dump-nonutf8-attr");
    assert!(
        output.status.success(),
        "oracle dump-nonutf8-attr failed (status {}):\nstderr:\n{}",
        output.status,
        String::from_utf8_lossy(&output.stderr)
    );
    let attr_bytes = std::fs::read(&attr_dump_path).expect("read oracle attr dump");
    assert_eq!(attr_bytes.len(), 8, "expected two little-endian i32s");
    let nonutf8_value = i32::from_le_bytes(attr_bytes[0..4].try_into().unwrap());
    let maxlen_value = i32::from_le_bytes(attr_bytes[4..8].try_into().unwrap());
    assert_eq!(
        nonutf8_value, NN_ATTR_NONUTF8_VALUE,
        "real C++ Header::findTypedAttribute must find our non-UTF-8-named attribute"
    );
    assert_eq!(
        maxlen_value, NN_ATTR_MAXLEN_VALUE,
        "real C++ Header::findTypedAttribute must find our 255-byte-named attribute"
    );

    eprintln!(
        "OK (b) our file with non-UTF-8 channel + attribute names, and a 255-byte \
         attribute name, read by the real C++ oracle: pixels and attribute values byte-exact."
    );
}
